delete from pb_ai.kb_shelf s using jsonb_array_elements($kb$[{"id": "dig-ca-tickets-1", "state": "CA", "tier": "shelf", "title": "California 811: ticket life, renewal, no-response, high priority lines", "topic": "811 tickets: types, ticket life, renewals and updates", "text": "California ticket rules (Gov. Code 4216.2, 4216.3). Notice: at least 2 working days, not more than 14 calendar days ahead. A ticket \"shall be valid for 28 days from the date of issuance.\" If work goes past 28 days, renew online or by calling 811 \"by the end of the 28th day.\" If the ticket expires while work is ongoing you must \"immediately cease excavation, contact the regional notification center, and get a new ticket,\" and wait again for the operators. You may not start until all operators listed on the ticket have marked, given location information, or said they have no lines there. Every operator must post an electronic positive response before the legal start date and time. If one does not, tell the 811 center (4216.3(d)). Marks faded or gone: stop in that area and ask the center for remarks; the operator has 2 working days, not counting the request day. High priority lines (gas over 60 psig, petroleum, pressurized sewage, 60 kV or more electric, hazardous materials): if you will dig within 10 feet, the operator sets an onsite meeting and you may not dig until it is done. Farms and flood control can get an \"area of continual excavation\" ticket; that is not for pipeline construction crews.", "source": "Cal. Gov. Code 4216, 4216.2, 4216.3, 4216.4, 4216.6 (FindLaw copy, current as of Jan 1, 2026)", "url": "https://codes.findlaw.com/ca/government-code/gov-sect-4216-2/", "checked": "2026-11-20", "edition": "Current as of January 1, 2026", "confidence": "high", "kind": "summary", "license": "gov-state"},
{"id": "dig-ca-marks-1", "state": "CA", "tier": "shelf", "title": "California 811: tolerance zone 24 inches, hand tools, white delineation", "topic": "811 marks: tolerance zone, hand digging, white lining, positive response", "text": "California tolerance zone: \"24 inches on each side of the field marking placed by the operator\" (Gov. Code 4216(u)). Before using any power-driven digging or boring equipment inside the zone you must \"determine the exact location of the subsurface installations in conflict with the excavation using hand tools\" (4216.4(a)(1)). A hand tool is one that \"uses human power and is not powered by any motor, engine, hydraulic, or pneumatic device.\" Exceptions in 4216.4(a)(2): a vacuum excavator may be used if you told the 811 center you intend to use one and the operator agrees; power equipment may remove existing pavement only if no known line is in the pavement. Can't find the line by hand digging: ask the operator for more information; the operator must answer within one working day. Treat every line as live: the law says to \"presume all subsurface installations to be active.\" White: delineate means \"to mark in white the location or path of the proposed excavation.\" An operator may wait to mark until the area is delineated. Operators mark known abandoned lines with an A inside a circle. Nonpressurized sewer lines, storm drains and drain lines are not \"subsurface installations\" under this law, so they may not be marked.", "source": "Cal. Gov. Code 4216, 4216.2, 4216.3, 4216.4, 4216.6 (FindLaw copy, current as of Jan 1, 2026)", "url": "https://codes.findlaw.com/ca/government-code/gov-sect-4216-4/", "checked": "2026-11-20", "edition": "Current as of January 1, 2026", "confidence": "high", "kind": "summary", "license": "gov-state"},
{"id": "dig-ga-tickets-1", "state": "GA", "tier": "shelf", "title": "Georgia 811: ticket life 30 days, two updates, large projects, PRIS", "topic": "811 tickets: types, ticket life, renewals and updates", "text": "Georgia ticket life (25-9-6(c)): digging may not take place more than 30 calendar days after the ticket's effective date; to keep going, \"an additional locate request with appropriate notice must be submitted.\" The added request can't make the area bigger. Georgia 811 calls this an Update: \"An Update extends the life of an existing Normal ticket. A new ticket will be generated.\" It can only be sent between the \"Updateable On\" and \"Update By\" dates on the ticket, and \"a Normal Ticket may be updated a maximum of two times\" (90 days in all). A third update needs a reason and is reported to the PSC. Jobs over 1 linear mile or over 90 days: call 811 and ask for the Large Project team. PRIS: you are \"responsible for being aware of all information timely entered into the PRIS\" before you dig. If an owner has not answered, Georgia 811 sends a second request; if there is still no answer by noon that business day you \"may proceed\" as long as \"there is no visible and obvious evidence of the presence of an unmarked underground facility\" (25-9-7(e)). Don't ask for re-marks over and over; an owner can bill up to $100 for one. Design locate request: owners answer within ten business days; it \"shall not be used for excavation purposes.\" Emergency tickets: no digging after 7 AM on the third business day after the request.", "source": "O.C.G.A. 25-9-4, 25-9-6, 25-9-7 (eff. Sept 1, 2022); Georgia 811 \"Ticket Actions in the Portal\" and \"Update\" guides", "url": "https://georgia811.com/wp-content/uploads/2025/03/Georgia-Dig-Law_090122.pdf", "checked": "2026-11-20", "effective": "2022-09-01", "confidence": "high", "kind": "summary", "license": "gov-state"},
{"id": "dig-nc-tickets-1", "state": "NC", "tier": "shelf", "title": "North Carolina 811: ticket life 28 days, updates, 3-hour notice, size limits", "topic": "811 tickets: types, ticket life, renewals and updates", "text": "North Carolina ticket life (87-122(a)): the notice expires 28 calendar days after the work start date, and \"No excavation or demolition may continue after this 28-day period unless\" a new notice is given in the same manner as the first. NC811's ticket system treats that as an Update, which \"Generates a new ticket number linked to the old one\" and must be processed before the \"Update By\" date (from the ticket software vendor's help page; NC811's own pages would not open). Size: a notice may cover one parcel, or the lesser of five adjoining parcels or a quarter mile, and only what can be finished in 28 days. Positive response (87-122(c)): confirm through the system that every operator has answered before you dig. If one has not, you may go ahead only if there are no visible signs of a line (pole, marker, pedestal, meter, valve). If there are signs, send an additional notice; the operator must mark \"within three hours from the time the additional notice is received.\" You may start before the 3 days are up only when all operators have already answered. Design notice (87-127): operators answer within 10 working days; it \"may not be used for excavation purposes.\" Underwater (subaqueous) lines: 10 to 20 full working days' notice.", "source": "N.C.G.S. 87-117, 87-120 to 87-127, 87-129 (Article 8A, as amended by S.L. 2025-21); Norfield CENTER LOGiX \"Types of Tickets\" help page", "url": "https://www.ncleg.net/EnactedLegislation/Statutes/HTML/ByArticle/Chapter_87/Article_8A.html", "checked": "2026-11-20", "edition": "Statute as amended by Session Law 2025-21", "confidence": "high", "kind": "summary", "license": "gov-state"},
{"id": "dig-ny-marks-1", "state": "NY", "tier": "shelf", "title": "New York 811: tolerance zone 2 feet, hand-dug test holes, 4-inch rule", "topic": "811 marks: tolerance zone, hand digging, white lining, positive response", "text": "New York tolerance zone (753-1.2): \"the distance of one-half of the known diameter plus two feet\" on either side of the designated center line; if the diameter is not known, two feet on either side. Verify before you dig (753-3.6): where the work area and tolerance zone overlap, you must verify \"the precise location, type, size, direction of run and depth\" of the line. Gas and liquid petroleum lines must be verified by hand-dug test holes \"at one or more points where the work area and tolerance zone overlap.\" Other lines: hand-dug test holes or another way the operator agrees to. Power equipment in the zone before that: only to remove pavement or masonry, \"but only to the depth of such pavement or masonry,\" unless the operator agrees in writing. After the line is verified, no power equipment \"closer than four inches in any direction\" from it unless the operator agrees in writing (753-3.8). White (753-3.2): you \"shall delineate the work area with white paint, white stakes or other white suitable markings\" when needed to identify it. Colors (753-4.7): yellow gas and petroleum; red electric; orange communications; blue water; green sewer; purple reclaimed water; pink survey; white the excavation site.", "source": "16 NYCRR Part 753 (DPS booklet; Part 753 dated Feb 21, 2023); Gen. Bus. Law 765 (May 9, 2025)", "url": "https://dps.ny.gov/system/files/documents/2025/06/ss753-booklet-2025.05.09-update.pdf", "checked": "2026-11-20", "edition": "Part 753 as of February 21, 2023; booklet updated May 9, 2025", "confidence": "high", "kind": "summary", "license": "gov-state"},
{"id": "dig-pa-tickets-1", "state": "PA", "tier": "shelf", "title": "Pennsylvania 811: notice 3 to 10 business days, no-response rule, complex projects", "topic": "811 tickets: types, ticket life, renewals and updates", "text": "Pennsylvania notice (73 P.S. 180(2.1)): \"not less than three nor more than ten business days in advance of beginning excavation or demolition work.\" A business day is any day but Saturday, Sunday or a legal holiday, midnight to midnight. The lawful start date is the scheduled start date on the ticket. The statute sets no ticket life in days; it is not confirmed here. It does require a new notice if you vacate the worksite for more than two business days without other arrangements with the facility owners (clause 14). No response: if a facility owner \"fails to respond to the excavator's timely request,\" the excavator may proceed, not before the lawful start date and using due care (clause 5). PA One Call's response system (KARL) shows each owner's code, such as \"001 Clear\" and \"003 Field Marked\"; \"999 Did not respond\" is a violation by the owner. Find an unmarked or wrongly marked line when you arrive: renotify PA One Call; if the owner gives nothing useful within three hours you may proceed with care (clause 20). Complex projects (more than one locate request, or long schedules): a complex project ticket needs 10 business days' notice and a preconstruction meeting; they are entered through Coordinate PA, as are design notifications.", "source": "73 P.S. 176, 180, 182.10 (Underground Utility Line Protection Law; FindLaw copy, current as of Jan 1, 2026); PA One Call presentation to the PUC (Sept 2025)", "url": "https://codes.findlaw.com/pa/title-73-ps-trade-and-commerce/pa-st-sect-73-180/", "checked": "2026-11-20", "edition": "Current as of January 1, 2026", "confidence": "medium", "kind": "summary", "license": "gov-state", "unconfirmed": "ticket life in days"},
{"id": "dig-nm-damage-1", "state": "NM", "tier": "shelf", "title": "New Mexico 811: no-response, 18 inches, line hits, emergency locates", "topic": "811 emergencies and what to do when a line is hit", "text": "New Mexico rules on site (18.60.5.15 and .16 NMAC): before you dig, determine that all lines have been marked or cleared. If an operator has not marked or given a positive response, call for a warning locate; operators should respond \"ideally within two hours.\" The rule does not say you may dig without a response. Within \"18 inches either side of a marking made by a UFO\" (an operator), expose the line \"by non-mechanical means or mechanical vacuum excavation methods\" before machine work. Potholing or vacuum work done only to expose or find lines does not itself need a locate request. Damage: \"stop excavating immediately,\" call 911 if appropriate, the operator and 811, and secure the site. Do not \"leave the scene until authorized\" by an emergency responder or the operator, unless you tried and could not reach them and the site is secured. Emergency locates are marked as soon as practical, ideally within 2 hours; the emergency notice is good until the emergency is over or 48 hours, whichever is longer. Commission staff can shut down a dig that is not in compliance. Willful violations carry the penalties in NMSA 62-14-8; amounts were not confirmed. Design and bid locates are separate ticket types; no relocates or extensions on them.", "source": "18.60.5 NMAC sections 7, 8, 10, 11, 12, 13, 15, 16, 17 (Public Regulation Commission, srca.nm.gov)", "url": "https://www.srca.nm.gov/parts/title18/18.060.0005.html", "checked": "2026-11-20", "edition": "18.60.5 NMAC as posted Nov 20, 2026", "confidence": "medium", "kind": "summary", "license": "gov-state", "unconfirmed": "penalty amounts (NMSA 62-14-8)"},
{"id": "std-onecall-winter-snow-1", "state": "US", "tier": "shelf", "title": "811 in winter: snow, frozen ground and locate marks", "topic": "Locate marks: winter, snow and bad weather", "text": "Snow and frozen ground do not suspend the dig law anywhere: you still need a ticket, the wait, and marks you can see before a machine goes in. White marks do not show on snow. Several one-call rules name another color for the excavator's pre-marks when snow is on the ground, and it is not the same everywhere: check your state's rule before you mark. Marks buried by snow, plowed off or washed out are \"no longer visible\" under every law read: stop in that area and call 811 for a remark, and allow the normal re-mark time. Protect marks with stakes or flags next to the paint when snow is coming, and take photos of the marks the day they go down. Operators may get more time to mark in bad weather under some state laws, but they have to say so before the deadline; check positive response instead of assuming. Frozen ground is not a reason to skip potholing. Hand tools, air or hot-water vacuum still have to find the line inside the tolerance zone before the bucket or a frost ripper works there. Examples from the laws and handbooks read on Nov 20, 2026: Illinois law and the Alaska handbook say black when snow is on the ground; the Dig Safe manual for New England recommends fluorescent pink; Georgia and South Carolina list ice and snow as extraordinary circumstances that let an operator post a later marking date; Louisiana extends the mark-by time for inclement weather.", "source": "State one-call laws and 811 center handbooks read Nov 20, 2026: 220 ILCS 50/10; AK handbook p. 3; Dig Safe manual p. 9; O.C.G.A. 25-9-3(17); SC811 manual p. 20; La. R.S. 40:1749.14(C)(3)", "url": "https://ilga.gov/legislation/ilcs/ilcs3.asp?ActID=1286", "checked": "2026-11-20", "edition": "Sources as read November 20, 2026", "confidence": "medium", "kind": "summary", "license": "summary"},
{"id": "osha-pl-heat-proposed-1", "state": "US", "tier": "shelf", "title": "What the proposed federal heat rule would require (not in force)", "topic": "Heat illness rules", "text": "OSHA's 2024 proposal, not in force, would add 29 CFR 1926.67 for construction, the same text as proposed 1910.148. Initial heat trigger: a heat index of 80 F (or a wet bulb globe temperature at the NIOSH alert limit): drinking water at 1 quart per employee per hour, a shaded or air-conditioned break area, paid rest breaks as needed, two-way communication, and acclimatization for new workers (for example 20, 40, 60 and 80 percent of a normal shift on days 1 to 4) and for workers back after more than 14 days away (50, 60, 80 percent on days 1 to 3). High heat trigger: a heat index of 90 F: a paid 15-minute rest break at least every two hours, a buddy system or a supervisor watching no more than 20 employees, and a hazard alert. A written plan would be required for employers with more than 10 employees, with a named heat safety coordinator. Exposure of 15 minutes or less in any 60 minutes would be exempt. None of this is enforceable until a final rule is published.", "source": "OSHA proposed rule text (NPRM published 2024-08-30), proposed 29 CFR 1910.148 and 1926.67", "url": "https://www.osha.gov/sites/default/files/Heat-NPRM-Final-Reg-Text.pdf", "checked": "2026-11-20", "edition": "Proposed rule text, 2024; read 2026-11-20", "confidence": "high", "kind": "summary", "license": "gov-us"},
{"id": "osha-pl-record-forms-1", "state": "US", "tier": "shelf", "title": "OSHA 300, 300A and 301: who keeps them and the dates", "topic": "Injury reporting and OSHA recordkeeping", "text": "29 CFR Part 1904. Employers with 10 or fewer employees at all times during the last calendar year do not have to keep the OSHA injury and illness records unless OSHA or the Bureau of Labor Statistics tells them to in writing (1904.1); construction is not one of the low-hazard industries exempt under 1904.2. Covered employers enter each recordable case on the OSHA 300 log and a 301 incident report within 7 calendar days of learning of it (1904.29). The OSHA 300A annual summary is certified by a company executive and posted from February 1 to April 30 of the following year (1904.32). The log, summary and incident reports are kept for 5 years (1904.33). Larger establishments also send 300A data to OSHA electronically each year (1904.41). Reporting a death, hospitalization, amputation or eye loss (1904.39) applies to every employer, with or without a log. These sections were not checked against the rule text on 2026-11-20, so the numbers here are unconfirmed until they are read; state plans may also require records from smaller employers.", "source": "29 CFR 1904.1, 1904.2, 1904.29, 1904.32, 1904.33, 1904.41", "url": "https://www.osha.gov/laws-regs/regulations/standardnumber/1904/", "checked": "2026-11-20", "edition": "29 CFR Part 1904 (not re-read 2026-11-20)", "confidence": "medium", "kind": "summary", "license": "gov-us", "unconfirmed": "yes"},
{"id": "osha-pl-health-lead-1", "state": "US", "tier": "shelf", "title": "Lead in construction: the OSHA limits", "topic": "Jobsite health: first aid, water, toilets, noise", "text": "29 CFR 1926.62 covers lead in construction, which a pipe crew can meet when cutting or burning old lead-jointed cast iron pipe, lead service lines, lead paint on steel, or lead-sheathed cable. The permissible exposure limit is 50 micrograms per cubic meter of air as an 8-hour average and the action level is 30. Until the employer has measured exposure, certain tasks are treated as over the limit and need respirators, protective clothing, change areas, hand washing, blood tests and training. Do not eat, drink or smoke in the work area, and wash before breaks. The numbers in this card were not checked against the rule text on 2026-11-20, so read the section before you rely on them.", "source": "29 CFR 1926.62(b), (c), (d)", "url": "https://www.ecfr.gov/current/title-29/section-1926.62", "checked": "2026-11-20", "edition": "29 CFR text (not re-read 2026-11-20)", "confidence": "medium", "kind": "summary", "license": "gov-us", "unconfirmed": "yes"},
{"id": "osha-pl-fire-1", "state": "US", "tier": "shelf", "title": "Fire extinguishers and fuel on a construction site", "topic": "Other OSHA construction rules", "text": "29 CFR 1926.150 and 1926.152. A fire extinguisher rated at least 2A is provided for each 3,000 square feet of protected building area, with travel distance to the nearest one not over 100 feet. At least one extinguisher rated 10B or higher is within 50 feet of any place where more than 5 gallons of flammable or combustible liquid or 5 pounds of flammable gas is used. Flammable liquids are kept in approved containers; safety cans for quantities of 5 gallons or less. Fueling: shut the engine off, no smoking or open flame, and keep an extinguisher at the fuel service area. Extinguishers are inspected and kept in working order. The numbers in this card were not checked against the rule text on 2026-11-20, so read the section before you rely on them.", "source": "29 CFR 1926.150(c)(1); 1926.152(a), (g)", "url": "https://www.ecfr.gov/current/title-29/section-1926.150", "checked": "2026-11-20", "edition": "29 CFR text (not re-read 2026-11-20)", "confidence": "medium", "kind": "summary", "license": "gov-us", "unconfirmed": "yes"},
{"id": "osha-pl-elec-gfci-1", "state": "US", "tier": "shelf", "title": "GFCI protection for cords and tools on a jobsite", "topic": "Electrical safety and lockout", "text": "29 CFR 1926.404(b)(1): the employer uses either ground-fault circuit interrupters or an assured equipment grounding conductor program to protect employees. With GFCIs, all 120-volt, single-phase, 15- and 20-ampere receptacle outlets on construction sites that are not part of the permanent wiring have approved GFCI protection. That covers generators, pumps, saws and lights run from temporary power; small portable generators of 5 kW or less with a two-wire ungrounded system are an exception in the rule. The other option is a written assured equipment grounding program with a competent person, visual inspection of cords before each day's use, and periodic continuity tests. The numbers in this card were not checked against the rule text on 2026-11-20, so read the section before you rely on them.", "source": "29 CFR 1926.404(b)(1)(i)-(iii)", "url": "https://www.ecfr.gov/current/title-29/section-1926.404", "checked": "2026-11-20", "edition": "29 CFR text (not re-read 2026-11-20)", "confidence": "medium", "kind": "summary", "license": "gov-us", "unconfirmed": "yes"},
{"id": "osha-pl-scaffold-1", "state": "US", "tier": "shelf", "title": "Scaffolds in brief: the numbers a pipe crew meets", "topic": "Other OSHA construction rules", "text": "29 CFR 1926 Subpart L (1926.450 to 1926.454). A scaffold carries its own weight plus at least 4 times the maximum intended load. Fall protection on a scaffold is required at more than 10 feet above a lower level, not 6 feet. A competent person inspects the scaffold before each work shift and after anything that could affect it, and scaffolds are erected, moved and taken down only under a competent person. Access by ladder, stair tower or ramp is needed when the platform is more than 2 feet above or below the access point. Inside a deep structure or wet well a scaffold is also inside a confined space, and both rules apply. The numbers in this card were not checked against the rule text on 2026-11-20, so read the section before you rely on them.", "source": "29 CFR 1926.451(a)(1), (e)(1), (f)(3), (f)(7), (g)(1)", "url": "https://www.ecfr.gov/current/title-29/section-1926.451", "checked": "2026-11-20", "edition": "29 CFR text (not re-read 2026-11-20)", "confidence": "medium", "kind": "summary", "license": "gov-us", "unconfirmed": "yes"},
{"id": "osha-pl-crane-basics-1", "state": "US", "tier": "shelf", "title": "Cranes on a pipe job: operator, signal person and keeping clear", "topic": "Equipment, vehicles, rigging and cranes", "text": "29 CFR 1926 Subpart CC applies when a crane, boom truck or similar hoisting machine sets structures, vaults, pipe or trench boxes. The operator is trained, certified or licensed, and evaluated by the employer on the machine (1926.1427). A signal person is needed when the point of operation is not in full view of the operator, when the view is blocked in the direction of travel, or when the operator or the person handling the load sees a need (1926.1419), and signal persons are qualified (1926.1428). Riggers are qualified. Hoisting routes that keep loads from passing over people are used where possible, and people stay out of the fall zone except those hooking, unhooking or guiding the load (1926.1425). A competent person inspects the crane each shift. Excavators and backhoes are excluded from Subpart CC. The numbers in this card were not checked against the rule text on 2026-11-20, so read the section before you rely on them.", "source": "29 CFR 1926.1419(a), 1926.1425, 1926.1427, 1926.1428, 1926.1412", "url": "https://www.ecfr.gov/current/title-29/section-1926.1427", "checked": "2026-11-20", "edition": "29 CFR text (not re-read 2026-11-20)", "confidence": "medium", "kind": "summary", "license": "gov-us", "unconfirmed": "yes"},
{"id": "osha-pl-concrete-1", "state": "US", "tier": "shelf", "title": "Rebar caps and concrete work rules", "topic": "Other OSHA construction rules", "text": "29 CFR 1926 Subpart Q. 1926.701(b): all protruding reinforcing steel, onto and into which employees could fall, is guarded to eliminate the hazard of impalement; ordinary small plastic mushroom caps do not stop impalement from a fall, so use caps or troughs made for it or bend the bars over. No employee works under concrete buckets while they are being raised or lowered into position. 1926.703: formwork is designed and braced to carry all loads, and forms and shores are not removed until the concrete can support its weight. 1926.704: precast pieces such as manhole sections, vaults and box culverts are supported so they cannot tip over or collapse until permanently connected, and no one is under a precast piece being lifted or tilted into position unless needed for the erection. The numbers in this card were not checked against the rule text on 2026-11-20, so read the section before you rely on them.", "source": "29 CFR 1926.701(b), (e); 1926.703(a), (e); 1926.704(a), (e)", "url": "https://www.ecfr.gov/current/title-29/section-1926.701", "checked": "2026-11-20", "edition": "29 CFR text (not re-read 2026-11-20)", "confidence": "medium", "kind": "summary", "license": "gov-us", "unconfirmed": "yes"},
{"id": "osha-pl-tunnel-1", "state": "US", "tier": "shelf", "title": "Tunnels, shafts and jacked pipe: when OSHA Subpart S applies", "topic": "Other OSHA construction rules", "text": "29 CFR 1926.800 covers the construction of underground tunnels, shafts, chambers and passageways, and cut-and-cover excavations that are connected to ongoing underground construction or that create conditions like underground construction. Work under Subpart S is outside the confined space rule (1926.1201(b)). Key duties: a check-in and check-out procedure so the surface knows who is underground; at least one designated person on duty above ground who can summon help; a competent person who tests the air as often as needed (oxygen at least 19.5 percent, and limits on flammable gas, carbon monoxide and hydrogen sulfide); mechanical ventilation; a classification as potentially gassy or gassy when methane is found; rescue teams or services arranged in advance; and emergency lighting for each person underground. Large-diameter jacking and microtunnel shafts and tunnels that people enter usually fall here, not under the trench rule. The numbers in this card were not checked against the rule text on 2026-11-20, so read the section before you rely on them.", "source": "29 CFR 1926.800(a), (c), (g), (j), (k)", "url": "https://www.ecfr.gov/current/title-29/section-1926.800", "checked": "2026-11-20", "edition": "29 CFR text (not re-read 2026-11-20)", "confidence": "medium", "kind": "summary", "license": "gov-us", "unconfirmed": "yes"},
{"id": "osha-pl-asbestos-pipe-1", "state": "US", "tier": "shelf", "title": "Asbestos cement (transite) pipe: the OSHA rule", "topic": "Other OSHA construction rules", "text": "29 CFR 1926.1101 covers asbestos in construction, including cutting, tapping, removing or repairing asbestos cement (AC, transite) water and sewer pipe. The permissible exposure limit is 0.1 fiber per cubic centimeter of air as an 8-hour average, with an excursion limit of 1.0 fiber over 30 minutes. Work on AC pipe is supervised by a competent person, uses wet methods and tools that do not make dust (snap cutters, wet hand tools; no dry abrasive saw cutting), and is done by trained workers. Waste pipe is kept wet, wrapped or bagged and labeled. State and local air rules and the owner's specifications often add notice and disposal steps. The numbers in this card were not checked against the rule text on 2026-11-20, so read the section before you rely on them.", "source": "29 CFR 1926.1101(c), (g), (k), (o)", "url": "https://www.ecfr.gov/current/title-29/section-1926.1101", "checked": "2026-11-20", "edition": "29 CFR text (not re-read 2026-11-20)", "confidence": "medium", "kind": "summary", "license": "gov-us", "unconfirmed": "yes"},
{"id": "mutcd-6a-principles-1", "state": "US", "tier": "shelf", "title": "MUTCD: the seven basic principles of temporary traffic control", "topic": "Traffic control: MUTCD basics and status", "text": "Section 6A.02 lists seven principles for every work zone. A, plan it: use the same safety thinking as a permanent road and have a traffic control plan that everyone understands before you occupy the road. B, slow traffic down as little as practical: drivers only slow when they see a clear need, so avoid abrupt changes, keep closures short and off-peak, and keep a path for bikes and pedestrians, including people with disabilities. C, guide drivers clearly: enough warning, delineation and channelizing, and cover or remove signs and markings that no longer apply. D, inspect: a knowledgeable person checks the setup day and night, changes it as the work changes, and can stop work until it is fixed. E, keep the roadside safe: crashworthy devices, and store equipment, trucks, materials and spoil where a car is not likely to hit them. F, train everyone whose decisions affect work zone safety, and only trained people supervise the choice and placement of devices. G, tell the public, the neighbors, emergency services and schools ahead of time. The same section says safety of road users and workers should be a high priority from planning through construction. Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Section 6A.02 paras. 1-2 (items A-G)", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"},
{"id": "mutcd-6b-detour-1", "state": "US", "tier": "shelf", "title": "Detour or diversion: the difference", "topic": "Traffic control: parts of a work zone", "text": "A detour sends road users onto another existing road to get around the work zone. A diversion sends them onto a temporary road or temporary alignment built around the work area, inside or next to the right-of-way (Section 6B.09). A detour should be signed over its whole length so drivers can get back to the road they were on. On a long detour, repeat the Detour signs so drivers know they are still on it (Section 6N.09). When a whole road is closed, warn drivers ahead of the last place they can turn off, and where local traffic can still reach homes and businesses use ROAD CLOSED AHEAD, LOCAL TRAFFIC ONLY. When the road is legally closed but local access stays open, the barricades usually do not span the full road and a sign has to state the permitted local access (Section 6K.07). Type 3 barricades are the device for a full or partial road closure. Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Sections 6B.09, 6N.09 paras. 2-5, 6K.07 paras. 18-22", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"},
{"id": "mutcd-6g-finesigns-1", "state": "US", "tier": "shelf", "title": "Work zone speed limit and higher fines signs", "topic": "Traffic control: advance warning signs", "text": "The MUTCD has the signs; the fine itself comes from state law. A WORK ZONE plaque (G20-5aP) may go above a Speed Limit sign, and an END WORK ZONE SPEED LIMIT sign (R2-12) may mark the end. Where higher fines apply, a BEGIN HIGHER FINES ZONE sign (R2-10) should be placed at or near the start of the zone and END HIGHER FINES ZONE (R2-11) at the end; the legend may say DOUBLE FINES instead, and a FINES HIGHER, FINES DOUBLE or dollar amount plaque may go under the Speed Limit sign (Section 6G.08). Many state laws only double the fine when these signs are up and workers are present, so missing signs can cost the enforcement. On speed limits themselves, Section 6B.01 says reduced speed zoning should be avoided as much as practical, kept to a 10 mph reduction or less where used, and placed only where there is a restrictive feature; a drop of more than 10 mph needs extra notice and a step-down. Only the agency with authority over the road can set a regulatory work zone speed limit. Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Section 6G.08 paras. 1-5; Table 6G-1; Section 6B.01 paras. 17-20", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"},
{"id": "mutcd-6k-peddevices-1", "state": "US", "tier": "shelf", "title": "Pedestrian channelizing devices: the cane-detectable barricade", "topic": "Traffic control: pedestrians and sidewalks", "text": "When work affects a sidewalk, pedestrian channelizing devices should be used to close it and to mark the temporary route (Section 6K.02). Requirements (Standard): devices that channel pedestrians shall be detectable to a person using a long cane and visible to people with low vision; used as a sidewalk closure, the device shall cover the whole width of the sidewalk; exposed to traffic, it shall be crashworthy. The device has a continuous detection plate at the bottom and a continuous hand-trailing edge at the top, in the same vertical plane: bottom of the plate no more than 2 inches above the walk, top of the plate at least 8 inches above it, and the top of the hand-trailing edge between 32 and 38 inches. Gaps between devices in a run should not be more than 1 inch. Where a continuous wall is used instead, its bottom edge is no more than 2 inches up and it reaches at least 32 inches. Barricade rail supports should not stick out more than 4 inches into the walking route between 27 and 80 inches above the surface (Section 6K.07). Cones with caution tape do not meet this. Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Section 6K.02 paras. 2-19; Section 6K.07 paras. 10-11; Figure 6K-2", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"},
{"id": "mutcd-6l-lights-1", "state": "US", "tier": "shelf", "title": "Warning lights and message signs in a work zone", "topic": "Traffic control: cones, drums, barricades and arrow boards", "text": "Warning lights (Section 6L.07) are yellow. Type A is a low-intensity flashing light for night, used on barricades and signs that warn of a hazard. Type B is a high-intensity flashing light for day and night, used on advance warning signs or its own support. Type C and Type D (360 degree) are steady-burn lights used in a row to show the edge of the traveled way at night. Rules (Standard): a light on a device used alone to warn shall flash; lights on a series of channelizing devices shall be steady-burn, except sequential lights in a merging taper, which flash in order from upstream to downstream; flashing lights shall not be used for delineation; the bottom of the lens is at least 30 inches high. Type A, C and D lights are visible from 3,000 ft on a clear night; Type B from 1,000 ft on a sunny day. Portable changeable message signs (Section 6L.05): should be readable from half a mile, with letters at least 18 inches tall, no more than two phases of three lines each, and should sit off the shoulder or behind barrier where practical; the bottom is at least 7 ft above the road in urban areas and 5 ft in rural areas. A flag tree (high-level warning device) has at least two flags and is meant to be seen over cars (Section 6L.08). Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Sections 6L.05 paras. 11-30, 6L.07 paras. 3-20, 6L.08 paras. 1-3", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"},
{"id": "mutcd-6l-afad-1", "state": "US", "tier": "shelf", "title": "Automated flagger assistance devices (AFAD)", "topic": "Traffic control: flaggers", "text": "An AFAD lets the flagger stand out of the lane and run a remote STOP/SLOW sign or a red/yellow light with a gate arm. Rules from Sections 6L.02 to 6L.04 (Standard): an AFAD shall be used only where there is one lane of approaching traffic to control; it shall be operated only by a flagger trained on that device, who shall not leave it unattended while it is in use; at night its location is lit like a flagger station. Two flaggers are used with the usual two methods of operation, unless one flagger has a clear view of both devices and of traffic from both directions. A STOP/SLOW AFAD has a sign at least 24 by 24 inches with letters at least 8 inches high, mounted with the bottom at least 6 ft above the pavement, and a WAIT ON STOP sign (R1-7) faces approaching drivers. A red/yellow lens AFAD has 12 inch circular red and yellow lenses and a STOP HERE ON RED sign on the right side of the approach. Advance signs should include ROAD WORK AHEAD and ONE LANE ROAD. Some states require the AFAD operator to hold the state's flagger card. Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Sections 6L.02 paras. 4-15, 6L.03 paras. 2-12, 6L.04 paras. 2-5", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"},
{"id": "mutcd-6m-barrier-1", "state": "US", "tier": "shelf", "title": "Temporary traffic barrier (K-rail) in a work zone", "topic": "Traffic control: cones, drums, barricades and arrow boards", "text": "Temporary traffic barrier keeps vehicles out of the work space; cones, drums and water-filled channelizers do not. Section 6M.02: the decision to use barrier is based on engineering judgment, looking at how close traffic is, its speed, the duration, and what is behind the line, such as an open trench or workers on foot. Requirements (Standard): temporary barrier, including the end treatment, shall be crashworthy; it shall be supplemented with delineation, pavement markings or channelizing devices so drivers can see it day and night; and short, separated pieces of barrier shall not be used, because gaps cancel the protection and create blunt ends. Steady-burn warning lights may be mounted on it. Where a pedestrian route runs close to traffic, the two should be separated with temporary traffic barrier, and ordinary vertical curb shall not be used in place of barrier where barrier is needed (Section 6C.02). Barrier deflects when hit, so leave room behind it. Positive protection may be added to any of the typical applications. Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Section 6M.02 paras. 7-11; Section 6C.02 paras. 20-23", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"},
{"id": "mutcd-6p-ta6-1", "state": "US", "tier": "shelf", "title": "TA-6: shoulder work that takes a little of the lane", "topic": "Traffic control: typical setups for utility work", "text": "TA-6 is for work on the shoulder that sticks a short way into the travel lane on a low-speed minor road. Notes: every lane left open should be at least 10 ft wide, measured to the near face of the cones (Guidance). For short-term work on a low-volume, low-speed road with no long or wide trucks, 9 ft may be used. If you cannot keep that width, or speeds are higher, close the lane instead. If the far shoulder is good and wide enough, the lanes may be shifted over with closely spaced devices, keeping 10 ft. A ROAD NARROWS sign may be added. A shadow vehicle sits upstream of the work; it may be left out if a taper and cones are used, and it may carry a truck-mounted attenuator. For short-duration work the taper and cones may be left out if a shadow vehicle with activated high-intensity lights is used. Shadow and work vehicles shall show high-intensity rotating, flashing, oscillating or strobe lights, and four-way flashers shall not be used in their place (Standard). Vehicle-mounted signs must not be blocked by equipment and are covered or turned when work is not in progress. Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Figure 6P-6 (TA-6) notes 1-14; Section 6N.07", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"},
{"id": "mutcd-6p-ta11-1", "state": "US", "tier": "shelf", "title": "TA-11, TA-13 and TA-18: low-volume roads, brief road closure, minor street", "topic": "Traffic control: typical setups for utility work", "text": "TA-11, lane closure on a two-lane road with low traffic volume: STOP or YIELD sign control may replace flaggers when traffic is light enough that drivers who must yield get gaps, and drivers from both ends can see through and beyond the work. Type B flashing lights may go on the ROAD WORK AHEAD and ONE LANE ROAD AHEAD signs for a night closure. TA-13, temporary road closure: for a planned full stop of no more than 20 minutes in the daytime, for example to set a structure or swing a load. A flagger or a uniformed officer shall be used (Standard); a BE PREPARED TO STOP sign may be added ahead of the Flagger sign. TA-18, lane closure on a minor street: only for low-speed streets with low volume (Standard). Where the work space is short and drivers can see through, traffic may regulate itself; where it cannot, one or two flaggers shall be used as in TA-10 (Standard). Flashing lights or flags may be put on the advance signs, and a truck-mounted attenuator may be used on the work or shadow vehicle. Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Figures 6P-11 (TA-11) notes 2-3, 6P-13 (TA-13) notes 1-7, 6P-18 (TA-18) notes 1-6", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"},
{"id": "mutcd-6p-ta15-1", "state": "US", "tier": "shelf", "title": "TA-15 and TA-26: work in the center of the road or the middle of an intersection", "topic": "Traffic control: typical setups for utility work", "text": "TA-15, work in the center of a low-volume road (a manhole in the centerline, for example): traffic passes on both sides. The lane on each side should be at least 10 ft wide, measured from the near edge of the cones to the edge of pavement or the outside edge of a paved shoulder; 9 ft may be used for short-term work on low-volume, low-speed roads without long or wide trucks. A work vehicle with activated high-intensity flashing lights may take the place of the cones in the tapers or of the flag tree. Warning lights may go on the cones if the closure stays overnight. TA-26, closure in the center of an intersection: all lanes at least 10 ft wide to the near face of the cones (9 ft on the same short-term, low-speed, low-volume condition). A flag tree may be set in the work space. Left turns may be prohibited where the geometry will not let large vehicles make them. For short-duration work the cones may be left out if a vehicle with activated high-intensity lights is in the work space. In both, four-way hazard flashers may be added but shall not replace the high-intensity lights (Standard). Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Figures 6P-15 (TA-15) notes 1-8, 6P-26 (TA-26) notes 1-8", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"},
{"id": "mutcd-6p-ta21-1", "state": "US", "tier": "shelf", "title": "TA-21, TA-22, TA-23 and TA-27: lane closures at an intersection", "topic": "Traffic control: typical setups for utility work", "text": "TA-21, near side: the merging taper shall direct traffic into either the right lane or the left lane, but not both (Standard). A left taper keeps right turns from holding up through traffic. A shadow vehicle with a truck-mounted attenuator may be used. TA-22, right lane closed on the far side: if the right lane carries a lot of right turns, the approach lane may be kept for right turns only, pushing through traffic to the left lane; where the approach is down to one lane, left turns may be prohibited to keep through traffic moving. TA-23, left lane closed on the far side: the left lane may reopen as a left-turn-only bay so turning cars do not block through traffic. TA-27, closure at the side of an intersection: flaggers or uniformed officers should direct traffic inside the intersection; ONE LANE ROAD AHEAD signs should be used, a BE PREPARED TO STOP sign goes ahead of the Flagger sign if used, and flagger stations shall be lit at night (Standard). The simplest fix is often to close one approach or send through traffic another way. In all of them: if the work space crosses a crosswalk, close the crosswalk as TA-29 shows. Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Figures 6P-21 notes 1-9, 6P-22 notes 1-8, 6P-23 notes 1-5, 6P-27 notes 1-12", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"},
{"id": "mutcd-6p-multilane-1", "state": "US", "tier": "shelf", "title": "TA-30, TA-33 and TA-35: lane closures on multi-lane roads", "topic": "Traffic control: typical setups for utility work", "text": "TA-30, interior lane closure on a multi-lane street: for low-speed, low-volume city streets; where speed or volume is higher add signs such as LEFT LANE CLOSED with the distance between the signs shown. Closing the inside lane of the opposite direction may not be needed. TA-33, stationary lane closure on a divided highway: lane closed signs and lane ends signs, a full merging taper of length L, a buffer, cones along the work and a downstream taper. When a shoulder 8 ft or wider is closed, cones should close the shoulder ahead of the merging taper. If a side road enters inside the zone, add devices for it (Standard). An arrow board shall be used when a freeway lane is closed, one board for each closed lane (Standard). TA-35, mobile operation on a multi-lane road: arrow boards shall be at least Type B, 60 by 30 inches; shadow and work vehicles shall show high-intensity flashing lights (Standard). The first shadow vehicle should carry an arrow board and a truck-mounted attenuator; keep the gaps between vehicles short so drivers do not cut in; work off-peak. Truck-mounted attenuators and other positive protection may be added to any of these. Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Figures 6P-30 notes 1-4, 6P-33 notes 1-7, 6P-35 notes 1-15", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"},
{"id": "mutcd-6p-ta17-1", "state": "US", "tier": "shelf", "title": "TA-17: mobile operation on a two-lane road", "topic": "Traffic control: short jobs and mobile work", "text": "TA-17 covers work that keeps moving on a two-lane road, with a work vehicle and a shadow vehicle behind it. Standard notes: vehicle-mounted signs shall be mounted so equipment or supplies do not hide them, and are covered or turned from view when work is not in progress; shadow and work vehicles shall display high-intensity rotating, flashing, oscillating or strobe lights; if an arrow board is used it shall be in caution mode; four-way flashers shall not be used in place of the high-intensity lights. Guidance: where practical the vehicles should pull over from time to time to let traffic by; the shadow vehicle should hold a steady distance behind the work vehicle and drop back before curves and hill crests so drivers coming from behind see it in time; the shadow vehicle should have two high-intensity flashing lights on the rear next to the sign. Options: more shadow vehicles, a truck-mounted attenuator on the shadow or work vehicle, and a DO NOT PASS sign on the rear of the blocking vehicle where the vehicles cannot pull over often. Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Figure 6P-17 (TA-17) notes 1-13", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"},
{"id": "tc-ca-buffer-1", "state": "CA", "tier": "shelf", "title": "California buffer space and flagger distance, including downgrades (Table 6B-2(CA))", "topic": "Traffic control: tapers and buffer spaces", "text": "California's CA MUTCD 2026 uses the national stopping sight distance table for a longitudinal buffer space or a flagger station on a level road, and adds Table 6B-2(CA) for downgrades. Level road (Table 6B-2): 25 mph 155 ft, 30 mph 200 ft, 35 mph 250 ft, 40 mph 305 ft, 45 mph 360 ft, 50 mph 425 ft, 55 mph 495 ft, 60 mph 570 ft, 65 mph 645 ft. Downgrades, as minus 3 percent, minus 6 percent, minus 9 percent: 25 mph 158, 165, 173 ft. 30 mph 205, 215, 227 ft. 35 mph 257, 271, 287 ft. 40 mph 315, 333, 354 ft. 45 mph 378, 400, 427 ft. 50 mph 446, 474, 507 ft. 55 mph 520, 553, 593 ft. 60 mph 598, 638, 686 ft. 65 mph 682, 728, 785 ft. Using the table for a buffer is an Option in Section 6B.06; no work, equipment, vehicles or material should be in the buffer. Flagger stations may be placed with the same distances and shall be lit at night except in emergencies (Section 6D.06).", "source": "CA MUTCD 2026, Section 6B.06 para. 11; Tables 6B-2 and 6B-2(CA); Section 6D.06 paras. 3, 5", "url": "https://dot.ca.gov/-/media/dot-media/programs/safety-programs/documents/ca-mutcd/2026/2026-camutcd-2026-6b-a11y.pdf", "checked": "2026-11-20", "confidence": "high", "kind": "summary", "license": "summary", "edition": "CA MUTCD 2026", "effective": "2026-01-18"},
{"id": "tc-ca-plans-1", "state": "CA", "tier": "shelf", "title": "California Caltrans standard plans for traffic control (T-series)", "topic": "Traffic control: typical setups for utility work", "text": "California State highway work uses the Caltrans Standard Plans for traffic control systems, which the CA MUTCD 2026 points to as T9 through T27 (Section 6B.08). From the 2026 Standard Plans digest: T9 carries the advance warning sign spacing table; T10 is the lane closure plan and T10A the complete closure and lane closure with partial shoulder use; T11 is a typical lane closure and T11A a changeable lane closure; T12 is a half-road closure; T13 covers reversible (one-lane, two-way) traffic control with flaggers, with T13B for residential driveways and low-volume side roads; T14 covers ramps; T15 and T16 are moving lane closures on multilane highways. A Caltrans encroachment permit will name the T-plan to use. City and county streets follow the CA MUTCD and the city's own permit conditions; many cities accept a T-plan or a typical application as the traffic control plan for a short utility job. Sheet titles for T13, T13A, T13C and T17 were not confirmed from the digest.", "source": "CA MUTCD 2026 Section 6B.08 para. 16; Caltrans 2026 Standard Plans digest (T9-T17)", "url": "https://dot.ca.gov/-/media/dot-media/programs/design/documents/2026-standard-plans-digest-a11y.pdf", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "summary", "edition": "Caltrans 2026 Standard Plans", "unconfirmed": "yes"},
{"id": "tc-wa-flagger-2", "state": "WA", "tier": "shelf", "title": "Washington flagging: sign sequence, flagger station distance, apparel and lighting", "topic": "Traffic control: flaggers", "text": "Washington's flagger rule, WAC 296-155-305, sets numbers the national manual leaves open. Advance warning signs: a three-sign sequence on roads posted below 45 mph and a four-sign sequence at 45 mph or higher. Flagger station distance ahead of the work space (Table 2): 20 mph 35 ft, 25 mph 55 ft, 30 mph 85 ft, 35 mph 120 ft, 40 mph 170 ft, 45 mph 220 ft, 50 mph 280 ft, 55 mph 335 ft, 60 mph 415 ft, 65 mph 485 ft; longer is acceptable. Flaggers stand on the shoulder next to the traffic they control or in the closed lane, and step into the lane only after traffic has stopped. Flaggers must not be exposed to traffic or equipment coming from behind unless there is a way to warn them, such as an observer or a mirror. Apparel in daylight: a Class 2 high-visibility garment and a high-visibility hard hat. In darkness, from half an hour before sunset to half an hour after sunrise: the Class 2 garment plus white coveralls or trousers with reflective leg bands, and a hard hat with at least 12 square inches of reflective material. Flagger stations are lit with floodlights at night, set so they do not glare at drivers. Sign spacing by road type is in the rule's Table 1; those values were not confirmed row by row here, so read the table.", "source": "WAC 296-155-305(4), (5), (8), (9) and Tables 1 and 2", "url": "https://www.law.cornell.edu/regulations/washington/WAC-296-155-305", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "gov-state", "edition": "WAC 296-155-305, last amended WSR 16-09-085", "effective": "2016-05-20", "unconfirmed": "yes"},
{"id": "tc-or-taper-1", "state": "OR", "tier": "shelf", "title": "Oregon taper lengths and cone counts by speed (OTTCH Table 2-3)", "topic": "Traffic control: tapers and buffer spaces", "text": "Oregon's Temporary Traffic Control Handbook 2026 prints taper lengths with the number of cones in Table 2-3. Merging taper for a 12 ft lane: 25 mph 125 ft (6 cones), 30 mph 180 ft (7), 35 mph 245 ft (8), 40 mph 320 ft (9), 45 mph 540 ft (13), 50 mph 600 ft (13), 55 mph 660 ft (13), 60 mph 720 ft (13), 65 mph 780 ft (13). For an 11 ft lane: 25 mph 115 ft, 30 mph 165 ft, 35 mph 225 ft, 40 mph 295 ft, 45 mph 495 ft, 55 mph 605 ft. For a 10 ft lane: 25 mph 105 ft, 30 mph 150 ft, 35 mph 205 ft, 40 mph 270 ft, 45 mph 450 ft, 55 mph 550 ft. Shifting tapers are half: 12 ft at 35 mph is 125 ft, at 45 mph 270 ft. Shoulder taper (10 ft shoulder): 25 mph 35 ft, 35 mph 70 ft, 45 mph 150 ft, 55 mph 185 ft. The formulas are the national ones (Tables 2-1 and 2-2). One-lane two-way and downstream tapers are 50 to 100 ft with 4 to 6 cones at 20 ft. Night flagger stations: lit separately from the work, light 15 to 21 ft high on the flagger's side, at least 5 foot-candles, flagger recognizable from 1,000 ft (sections 3.8, 4.3). Sign spacing and buffer lengths are in Table 2-4; those values were not confirmed here because the table did not read cleanly.", "source": "Oregon Temporary Traffic Control Handbook 2026, Tables 2-1, 2-2, 2-3; sections 2.3, 3.8, 4.3", "url": "https://www.oregon.gov/odot/Engineering/Docs_TrafficEng/OTTCH-2026.pdf", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "summary", "edition": "OTTCH 2026 Edition, January 2026", "unconfirmed": "yes"},
{"id": "mfr-pvcpa-sewer-1", "state": "US", "tier": "shelf", "title": "PVC sewer pipe (SDR 35, SDR 26, ASTM D3034): installation basics from the PVC Pipe Association guide", "topic": "Pipe installation guides by material", "text": "PVC gravity sewer pipe installation, summarized from the Uni-Bell PVC Pipe Association guide for solid-wall PVC sewer pipe (PUB-06-25). Product standard is ASTM D3034; the guide notes that since 2024 D3034 covers 3 through 60 inch, so old references to ASTM F679 for 18 inch and up are being replaced. Common stiffness classes: DR 35 and DR 26 in 4 to 15 inch; PS 46, PS 75 and PS 115 in 18 to 60 inch. Installation practice is ASTM D2321. Nothing larger than 1-1/2 inches should touch the pipe. Bedding is typically 4 to 6 inches; dig bell holes only as big as needed; bring an over-dug bottom back to grade for the full length, not just at the bells. Haunching: work material under the haunches and at least halfway up the pipe and compact it (shovel slicing works). Initial backfill: at least 6 inches over the pipe, rock free, before any machine compaction over the top. Flotation: keep the trench dry until there is about 2 pipe diameters of backfill over thin-wall pipe (DR 32.5 and higher) or 1-1/2 diameters over heavier pipe. Joints: lubricate per the maker, push until the insertion line is even with the bell lip, and do not over-insert; re-bevel and re-mark field cuts. Bending: rule of thumb radius is 200 times the pipe OD, and bending pipe over 12 inch is not recommended; do not bend and deflect the joint on the same length. Acceptance: clean, then CCTV; a go/no-go mandrel sized for 7-1/2 percent deflection per D3034 (many specs require 5 percent); low-pressure air per ASTM F1417.", "source": "Uni-Bell PVC Pipe Association, Installation Guide for Solid-Wall PVC Sewer Pipe, PUB-06-25 (our summary; read 2026-11-20)", "url": "https://www.uni-bell.org/portals/0/resourcefile/installation-guide-for-solid-wall-pvc-sewer-pipe.pdf", "checked": "2026-11-20", "edition": "PUB-06-25", "confidence": "medium", "kind": "summary", "license": "summary"},
{"id": "mfr-dipra-install-1", "state": "US", "tier": "shelf", "title": "Ductile iron pipe: laying conditions Types 1 to 5, cover, trench width, polywrap (DIPRA guide)", "topic": "Pipe installation guides by material", "text": "Ductile iron pipe laying, summarized from the DIPRA Installation Guide for Ductile Iron Pipe (revised May 2015). Laying conditions (the trench types used in AWWA C150 and C600): Type 1 flat-bottom trench with loose backfill (not for 14 inch and larger); Type 2 flat-bottom trench, backfill lightly consolidated to the pipe centerline; Type 3 pipe bedded in at least 4 inches of loose soil, backfill lightly consolidated to the top of the pipe; Type 4 bedding of sand, gravel or crushed stone to 1/8 of the pipe diameter (4 inch minimum), backfill compacted to about 80 percent Standard Proctor; Type 5 bedded to the centerline in compacted granular material (4 inch minimum under the pipe), backfill compacted to about 90 percent Standard Proctor. The plans say which type. Cover is generally 2.5 to 3 feet minimum, deeper in frost country. Keep rock at least 6 inches away from pipe 24 inch and smaller and 9 inches from 30 inch and larger. Polyethylene encasement (AWWA C105) in corrosive soil: one tube per pipe length, overlapped about 1 foot at joints, taped at the ends and about every 2 feet, with slack at the joints; repair tears with tape. Before tapping polywrapped pipe, wrap 2 to 3 layers of tape around the pipe at the tap. Direct taps: 3/4 inch on all sizes, 1 inch on 6 inch and larger; bigger services need a saddle or tapping sleeve per the guide's table.", "source": "Ductile Iron Pipe Research Association (DIPRA), Installation Guide for Ductile Iron Pipe, revised May 2015, hosted by McWane (our summary; read 2026-11-20)", "url": "https://pe.mcwane.com/upl/downloads/dipra/dip-installation-guide-ab36416e.pdf", "checked": "2026-11-20", "edition": "2015", "confidence": "high", "kind": "summary", "license": "summary"},
{"id": "mfr-acpa-install-1", "state": "US", "tier": "shelf", "title": "Concrete pipe (RCP) Standard Installations Types 1 to 4: bedding thickness and compaction (ACPA, ASTM C1479)", "topic": "Pipe installation guides by material", "text": "Reinforced concrete pipe installation, summarized from the American Concrete Pipe Association installation manual. The four Standard Installations (Type 1 best, Type 4 least effort) are the same ones in ASTM C1479 and ASCE 15, and the plans say which type the pipe class was designed for. Bedding thickness under the pipe: outside diameter divided by 24, not less than 3 inches; on rock, outside diameter divided by 12, not less than 6 inches. Leave the middle bedding under the pipe loose so the pipe seats. Soil categories: I clean gravelly sand, II sandy silt, III silty clay. Haunch and outer bedding compaction (Standard Proctor): Type 1, 95 percent Category I; Type 2, 90 percent Category I or 95 percent Category II; Type 3, 85 percent Category I, 90 percent II or 95 percent III; Type 4, none needed except 85 percent if Category III soil is used. Lower side: Type 1, 90 percent I, 95 percent II or 100 percent III; Types 2 and 3, 85 percent I, 90 percent II or 95 percent III. Trench width guide: 1.25 times the pipe outside diameter plus 1 foot. Lay from the outlet end with bells upstream; clean and lubricate bell, spigot and gasket; bar and block works up to about 24 inch, larger pipe needs a puller. Put at least 3 feet of compacted backfill over pipe or box before equipment crosses unless it was designed for that load.", "source": "American Concrete Pipe Association, Concrete Pipe and Box Culvert Installation manual (our summary; read 2026-11-20). Standard Installations are the ones in ASTM C1479 and ASCE 15.", "url": "https://concretepipe.org/wp-content/uploads/2014/07/installation_guide.pdf", "checked": "2026-11-20", "edition": "undated", "confidence": "medium", "kind": "summary", "license": "summary"},
{"id": "mfr-westlake-c900-1", "state": "US", "tier": "shelf", "title": "C900 PVC water pipe installation (AWWA C605): trench, cover, joints, bending, testing rules", "topic": "Pipe installation guides by material", "text": "C900 PVC pressure pipe installation, summarized from Westlake Pipe's 2025 installation guides, which follow AWWA C605 (the PVC pressure pipe installation standard) and AWWA manual M23. Trench: clear width at the pipe springline at least 18 inches or pipe OD plus 1 foot, whichever is greater; no more than pipe diameter plus 2 feet at the crown; 4 inches of soil cushion where there is rock. Embedment: work material under the haunches, particle size 3/4 inch or smaller, at least 1 foot of initial backfill over the crown, compacted to what the engineer specifies. Cover: 24 inches under heavy traffic (ASTM D2774). Flotation: about 1.5 pipe diameters of cover. Joints: clean, check the gasket, lubricate the spigot bevel and the gasket with potable-safe lubricant, keep the lengths straight and push to the insertion line without over-inserting. Joint deflection for this pipe is only 1 degree (about 4-3/16 inches of offset on a 20-foot length). Bending the barrel instead is allowed by hand in 12 inch and smaller: minimum radius about 100 feet for 4 inch, 144 feet for 6 inch, 189 feet for 8 inch, 231 feet for 10 inch, 275 feet for 12 inch; never bend and deflect the same length. PVC grows or shrinks about 0.36 inch per 100 feet for each 10 F. Field cuts: square, bevel, re-mark the insertion line. No direct taps on C909 PVCO pipe. Testing: water only, never air; fill at 1 foot per second or less and vent high points; never test above the pipe's pressure rating; disinfect per AWWA C651. Up to two years of outdoor sun exposure is acceptable. Other makers' limits differ, so use the guide for the pipe on the truck.", "source": "Westlake Pipe & Fittings, Installation Guide for C900 PVC and C909 PVCO pressure pipe, MU-IG-013-US-EN-1025.1, 2025; and Municipal Installation Guide MU-IG-017, 2025 (our summary; read 2026-11-20). Both follow AWWA C605.", "url": "https://www.westlakepipe.com/sites/default/files/2025-10/mu-ig-013-us-en-1025.1_c900-pvc-c909-pvco.pdf", "checked": "2026-11-20", "edition": "2025", "confidence": "high", "kind": "summary", "license": "summary"},
{"id": "mfr-jmeagle-solvent-1", "state": "US", "tier": "shelf", "title": "JM Eagle solvent-weld PVC pipe and conduit: trench, cover, cement set times (JME-07B)", "topic": "Pipe installation guides by material", "text": "Solvent-weld PVC pressure pipe and PVC electrical conduit, summarized from JM Eagle's installation guide JME-07B (revised March 2011). Bedding 4 to 6 inches compacted, with bell holes; on rock, a cushion of at least 4 inches of sand or select backfill (6 inches in rock cuts). Haunching and initial backfill by hand, no rocks over 1.5 inches, tamped in layers of 6 inches or less, to at least 1 foot above the pipe; 90 percent density under pavement. Trench width: pipe OD plus 1 foot minimum at the springline, pipe OD plus 2 feet maximum at the top of the pipe. Cover: 12 inches where frost is not a concern, otherwise 6 inches below the deepest recorded frost. No rolling equipment until 18 inches of backfill is over the pipe; hydro-hammers need at least 3 feet. Solvent joints: dry fit (pipe should go 1/3 to 3/4 of the way into the socket), prime, cement both parts, push home with a quarter turn, look for a full bead. Minimum set time before handling: 30 minutes at 60 to 100 F, 1 hour at 40 to 60 F, 2 hours at 20 to 40 F, 4 hours at 0 to 20 F. No deflection at solvent joints: make curves by bending the pipe; snake small pipe in the trench. Pressure test is generally 25 percent above normal operating pressure and never above the pipe's rating. Never use compressed air or gas in PVC pressure pipe. JM Eagle's gravity sewer guide is JME-05B.", "source": "JM Eagle (J-M Manufacturing), Solvent Weld and Electrical Conduit Installation Guide, JME-07B, revised March 2011 (our summary; read 2026-11-20)", "url": "https://images.thdstatic.com/catalog/pdfImages/55/5515bbf2-b7ff-4f77-b3f6-c061e3e6beec.pdf", "checked": "2026-11-20", "edition": "2011", "confidence": "high", "kind": "summary", "license": "summary"},
{"id": "mfr-contech-cmp-1", "state": "US", "tier": "shelf", "title": "Corrugated metal pipe (CMP) installation: bedding, 8-inch lifts, 90 percent, balanced backfill, cover (Contech)", "topic": "Pipe installation guides by material", "text": "Corrugated metal pipe installation, summarized from Contech's CMP Installation Guide (June 2023). Bedding: 4 to 6 inches of well-graded granular material on a firm foundation; dig out soft spots and replace with granular fill. Backfill: angular, well-graded granular soil (AASHTO A-1, A-2 or A-3), nothing over 3 inches, placed in loose lifts of about 8 inches and compacted to 90 percent of AASHTO T99 (95 percent in the haunches of pipe-arch). Work material into the haunches with a shovel or rod. Keep the two sides balanced: never let one side get more than 24 inches higher than the other, including between barrels. Use flowable fill (CLSM) in thin lifts where barrels are too close to compact, letting each lift set so the pipe does not float. Minimum cover for highway loads is span divided by 8 (not less than 12 inches in common practice), in place and compacted before traffic. Light tracked equipment such as a small dozer needs at least 12 inches of compacted cover; heavy construction equipment needs more per the guide's tables. Lay from the downstream end and build the outlet first so rain can drain. Unload with forks or non-metallic slings; never dump pipe off the truck or lift bundles by the strapping.", "source": "Contech Engineered Solutions, CMP Installation Guide, June 2023 (our summary; read 2026-11-20)", "url": "https://conteches.com/media/uyslalti/cmp-installation-guide.pdf", "checked": "2026-11-20", "edition": "2023", "confidence": "high", "kind": "summary", "license": "summary"},
{"id": "mfr-westlake-sewer-1", "state": "US", "tier": "shelf", "title": "PVC gravity sewer pipe (SDR 35): cover before traffic, joint deflection and bending limits (Westlake guide)", "topic": "Pipe installation guides by material", "text": "PVC gravity sewer pipe (ASTM D3034), summarized from Westlake Pipe's 2024 installation guide. Embedment follows ASTM D2321 Classes I to IV. Cover before traffic crosses: 24 inches or one pipe diameter, whichever is larger, with Class I (crushed rock) embedment; 36 inches or one pipe diameter with Classes II to IV; 48 inches before a hydrohammer is used over the pipe. Flotation: about 1.5 pipe diameters of cover for SDR 32.5 and heavier pipe. Deflection: the guide uses 7.5 percent maximum at 30 days (ASTM D3034 appendix), checked with a go/no-go mandrel after 30 days; many agencies specify 5 percent. Joints: clean, lubricate the spigot bevel and gasket, keep the lengths straight, push with bar and block until the bell edge is on the insertion line, and do not over-insert. Joint deflection for this pipe is 1 degree: about 2.9 inches of offset on a 14-foot length and 4.2 inches on a 20-foot length. Bending the barrel by hand instead: minimum radius about 35 feet for 4 inch, 52 feet for 6 inch, 70 feet for 8 inch, 85 feet for 10 inch, 104 feet for 12 inch and 128 feet for 15 inch; not recommended above 15 inch; never bend and deflect the same length. Low-pressure air testing follows ASTM F1417. Laying lengths are 14 and 20 feet.", "source": "Westlake Pipe & Fittings, ASTM D3034 PVC Gravity Sewer Pipe Installation Guide, MU-IG-003-US-EN-0724.1, 2024 (our summary; read 2026-11-20)", "url": "https://www.westlakepipe.com/sites/default/files/2024-10/mu-ig-003-us-en-0724.1_astm-d3034.pdf", "checked": "2026-11-20", "edition": "2024", "confidence": "high", "kind": "summary", "license": "summary"},
{"id": "fed-epa-cgp-paperwork-1", "state": "US", "title": "SWPPP paperwork for the office: NOI, plan on site, records 3 years, termination in 30 days", "topic": "Stormwater on the job: construction general permit, SWPPP, inspections, dewatering", "text": "Office checklist from EPA's 2022 Construction General Permit. Before work: write the stormwater pollution prevention plan (SWPPP) before filing the Notice of Intent (Part 7.1), and file the NOI \"At least 14 calendar days before commencing construction activities\" (Part 1.4.3). During work: keep a current SWPPP \"at the site or at an easily accessible location\" so it can be shown to an inspector (Part 7.3); update it when the controls or the plan change. Use a qualified inspector (EPA course and exam, or an equivalent current certification, for projects covered on or after February 17, 2023; Part 6.3). Log every corrective action and close it within the permit's deadlines (7 calendar days for a new or replaced control or significant repair). Records: keep inspection reports and the corrective action log \"for at least three (3) years\" after coverage ends (Parts 4.7.4, 5.4.4). After work: file the Notice of Termination \"within 30 calendar days after any one of the conditions in Part 8.2 occurs\", for example the site is finally stabilized or another operator has taken over (Part 8.4). A pipe subcontractor is often a co-operator or works under the general contractor's SWPPP: get that in writing and know which controls are yours to maintain. These are EPA's own permit numbers. Most states issue their own permit, usually close to this, and the state permit governs there.", "source": "EPA 2022 Construction General Permit, as modified April 2025, Parts 1.4.3, 6.3, 7.1, 7.3, 4.7.4, 5.4.4, 8.4", "url": "https://www.epa.gov/system/files/documents/2025-04/2022-cgp-permit-as-modified.pdf", "checked": "2026-11-20", "edition": "2022 CGP as modified (effective April 8, 2025); expires February 16, 2027", "confidence": "high", "kind": "summary", "license": "gov-us", "tier": "shelf"},
{"id": "fed-achp-discovery-1", "state": "US", "title": "Bones, artifacts or old foundations in the trench: stop and call it in", "topic": "Unexpected finds in the trench: human remains and artifacts", "text": "If the bucket turns up bones that could be human, a burial, arrowheads or other artifacts, old bottles and foundations, or anything that looks like an archaeological site: stop digging at that spot, keep people and equipment off it, do not move or pocket anything, and call the foreman, who calls the owner or inspector. Possible human remains also means a call to the police or the county coroner or medical examiner. On a job with federal money, a federal permit or federal land, the project went through historic review (Section 106), and 36 CFR 800.13 covers a find after construction has started: the federal agency must \"make reasonable efforts to avoid, minimize or mitigate adverse effects\" and, once construction is under way, notify the state or tribal historic preservation officer, affected tribes and the Advisory Council within 48 hours of the discovery; they have 48 hours to respond. Many projects have a written \"inadvertent discovery plan\" in the permit or specs that names who to call: ask for it at the preconstruction meeting. State law usually has its own stop-work rule for human remains. For example the California Health and Safety Code, section 7050.5, says \"there shall be no further excavation or disturbance of the site\" until the county coroner has decided, and the coroner calls the Native American Heritage Commission within 24 hours if the remains may be Native American. Work can usually go on elsewhere on the job while the spot is checked.", "source": "36 CFR 800.13(b) (post-review discoveries); Cal. Health and Safety Code 7050.5(b)-(c) as an example of state law", "url": "https://codes.findlaw.com/cfr/title-36-parks-forests-and-public-property/cfr-sect-36-800-13/", "checked": "2026-11-20", "edition": "36 CFR Part 800 as shown on codes.findlaw.com, read 2026-11-20", "confidence": "medium", "kind": "summary", "license": "gov-us", "tier": "shelf"},
{"id": "fed-law-miller-act-1", "state": "US", "title": "Not getting paid on a federal job: the Miller Act payment bond (90 day notice, 1 year to sue)", "topic": "Prevailing wage paperwork: certified payroll and payment bonds", "text": "You cannot lien federal property. Instead the Miller Act (40 U.S.C. 3131 to 3134) makes the prime contractor post a payment bond \"Before any contract of more than $100,000 is awarded\" for a federal construction job (the acquisition regulations set the working threshold higher; the library's bonds chunk gives $150,000). Who can claim: subcontractors and suppliers who dealt directly with the prime, and second-tier subs and suppliers who dealt with a first-tier subcontractor. Third tier and below are generally not covered. First tier (contract with the prime): no notice is needed; a claimant who \"has not been paid in full within 90 days after the day on which the person did or performed the last of the labor\" or furnished the last material may sue on the bond. Second tier (contract with a subcontractor, none with the prime): must give \"written notice to the contractor within 90 days\" of its last labor or material, stating the amount and who the work was done for, sent \"by any means that provides written, third-party verification of delivery to the contractor\" (certified mail or a delivery service with a receipt). Deadline to sue for everyone: the suit \"must be brought no later than one year after the day on which the last of the labor was performed\" or material supplied. Punch-list and warranty work may not extend that date. A waiver of these rights signed before the work is done is void. Get the bond copy from the contracting officer at the start of the job. For a real claim, use a construction attorney: the dates are strict.", "source": "40 U.S.C. 3131(b), 3133(b)(1), (b)(2), (b)(4), (c) (U.S. Code 2023 edition)", "url": "https://www.govinfo.gov/content/pkg/USCODE-2023-title40/html/USCODE-2023-title40-subtitleII-partA-chap31-subchapIII.htm", "checked": "2026-11-20", "edition": "U.S. Code, 2023 edition", "confidence": "high", "kind": "summary", "license": "gov-us", "tier": "shelf"},
{"id": "lic-ca-prelim-notice-1", "state": "CA", "title": "California 20-day preliminary notice: protecting the right to get paid (private and public jobs)", "topic": "Getting paid: preliminary notices, liens and stop payment notices", "checked": "2026-11-20", "confidence": "high", "kind": "summary", "license": "gov-state", "text": "In California a subcontractor or supplier keeps its right to a mechanics lien, a stop payment notice or a payment bond claim by giving a preliminary notice early in the job. Private jobs (Civil Code 8204): the notice is due \"not later than 20 days after the claimant has first furnished work\" on the job. A late notice still helps, but then the lien, stop payment notice or bond claim only covers work \"performed within 20 days prior to the service of the preliminary notice\" and after it. So every day late is money that can no longer be secured. Public works (Civil Code 9300): before giving a stop payment notice or making a payment bond claim, the claimant gives preliminary notice to \"The public entity.\" and \"The direct contractor to which the claimant provides work.\" Two groups do not have to give it on public works: \"A laborer is not required to give preliminary notice\", and neither is a claimant with a direct contract with the direct (prime) contractor. So a pipe sub hired by the general contractor on a city job is exempt, but its pipe supplier and its own subs are not. Public property cannot be liened; the stop payment notice and the payment bond are the remedies there. Office habit that works: send the notice by certified mail on every job in the first week, before there is any problem. For a real claim, the later deadlines are strict: use a construction attorney.", "source": "Cal. Civil Code 8204 and 9300 (as shown on california.public.law); read 2026-11-20", "url": "https://california.public.law/codes/ca_civ_code_section_8204", "edition": "California Civil Code as shown 2026-11-20", "note": "No library collection exists for state payment / lien law; filed under lic- for now. The architecture helper should say where it belongs.", "tier": "shelf"}]$kb$::jsonb) e
 where e->>'supersedes' is not null and s.id = e->>'supersedes' and s.id <> e->>'id';
insert into pb_ai.kb_shelf (id, chunk)
select e->>'id', e from jsonb_array_elements($kb$[{"id": "dig-ca-tickets-1", "state": "CA", "tier": "shelf", "title": "California 811: ticket life, renewal, no-response, high priority lines", "topic": "811 tickets: types, ticket life, renewals and updates", "text": "California ticket rules (Gov. Code 4216.2, 4216.3). Notice: at least 2 working days, not more than 14 calendar days ahead. A ticket \"shall be valid for 28 days from the date of issuance.\" If work goes past 28 days, renew online or by calling 811 \"by the end of the 28th day.\" If the ticket expires while work is ongoing you must \"immediately cease excavation, contact the regional notification center, and get a new ticket,\" and wait again for the operators. You may not start until all operators listed on the ticket have marked, given location information, or said they have no lines there. Every operator must post an electronic positive response before the legal start date and time. If one does not, tell the 811 center (4216.3(d)). Marks faded or gone: stop in that area and ask the center for remarks; the operator has 2 working days, not counting the request day. High priority lines (gas over 60 psig, petroleum, pressurized sewage, 60 kV or more electric, hazardous materials): if you will dig within 10 feet, the operator sets an onsite meeting and you may not dig until it is done. Farms and flood control can get an \"area of continual excavation\" ticket; that is not for pipeline construction crews.", "source": "Cal. Gov. Code 4216, 4216.2, 4216.3, 4216.4, 4216.6 (FindLaw copy, current as of Jan 1, 2026)", "url": "https://codes.findlaw.com/ca/government-code/gov-sect-4216-2/", "checked": "2026-11-20", "edition": "Current as of January 1, 2026", "confidence": "high", "kind": "summary", "license": "gov-state"},
{"id": "dig-ca-marks-1", "state": "CA", "tier": "shelf", "title": "California 811: tolerance zone 24 inches, hand tools, white delineation", "topic": "811 marks: tolerance zone, hand digging, white lining, positive response", "text": "California tolerance zone: \"24 inches on each side of the field marking placed by the operator\" (Gov. Code 4216(u)). Before using any power-driven digging or boring equipment inside the zone you must \"determine the exact location of the subsurface installations in conflict with the excavation using hand tools\" (4216.4(a)(1)). A hand tool is one that \"uses human power and is not powered by any motor, engine, hydraulic, or pneumatic device.\" Exceptions in 4216.4(a)(2): a vacuum excavator may be used if you told the 811 center you intend to use one and the operator agrees; power equipment may remove existing pavement only if no known line is in the pavement. Can't find the line by hand digging: ask the operator for more information; the operator must answer within one working day. Treat every line as live: the law says to \"presume all subsurface installations to be active.\" White: delineate means \"to mark in white the location or path of the proposed excavation.\" An operator may wait to mark until the area is delineated. Operators mark known abandoned lines with an A inside a circle. Nonpressurized sewer lines, storm drains and drain lines are not \"subsurface installations\" under this law, so they may not be marked.", "source": "Cal. Gov. Code 4216, 4216.2, 4216.3, 4216.4, 4216.6 (FindLaw copy, current as of Jan 1, 2026)", "url": "https://codes.findlaw.com/ca/government-code/gov-sect-4216-4/", "checked": "2026-11-20", "edition": "Current as of January 1, 2026", "confidence": "high", "kind": "summary", "license": "gov-state"},
{"id": "dig-ga-tickets-1", "state": "GA", "tier": "shelf", "title": "Georgia 811: ticket life 30 days, two updates, large projects, PRIS", "topic": "811 tickets: types, ticket life, renewals and updates", "text": "Georgia ticket life (25-9-6(c)): digging may not take place more than 30 calendar days after the ticket's effective date; to keep going, \"an additional locate request with appropriate notice must be submitted.\" The added request can't make the area bigger. Georgia 811 calls this an Update: \"An Update extends the life of an existing Normal ticket. A new ticket will be generated.\" It can only be sent between the \"Updateable On\" and \"Update By\" dates on the ticket, and \"a Normal Ticket may be updated a maximum of two times\" (90 days in all). A third update needs a reason and is reported to the PSC. Jobs over 1 linear mile or over 90 days: call 811 and ask for the Large Project team. PRIS: you are \"responsible for being aware of all information timely entered into the PRIS\" before you dig. If an owner has not answered, Georgia 811 sends a second request; if there is still no answer by noon that business day you \"may proceed\" as long as \"there is no visible and obvious evidence of the presence of an unmarked underground facility\" (25-9-7(e)). Don't ask for re-marks over and over; an owner can bill up to $100 for one. Design locate request: owners answer within ten business days; it \"shall not be used for excavation purposes.\" Emergency tickets: no digging after 7 AM on the third business day after the request.", "source": "O.C.G.A. 25-9-4, 25-9-6, 25-9-7 (eff. Sept 1, 2022); Georgia 811 \"Ticket Actions in the Portal\" and \"Update\" guides", "url": "https://georgia811.com/wp-content/uploads/2025/03/Georgia-Dig-Law_090122.pdf", "checked": "2026-11-20", "effective": "2022-09-01", "confidence": "high", "kind": "summary", "license": "gov-state"},
{"id": "dig-nc-tickets-1", "state": "NC", "tier": "shelf", "title": "North Carolina 811: ticket life 28 days, updates, 3-hour notice, size limits", "topic": "811 tickets: types, ticket life, renewals and updates", "text": "North Carolina ticket life (87-122(a)): the notice expires 28 calendar days after the work start date, and \"No excavation or demolition may continue after this 28-day period unless\" a new notice is given in the same manner as the first. NC811's ticket system treats that as an Update, which \"Generates a new ticket number linked to the old one\" and must be processed before the \"Update By\" date (from the ticket software vendor's help page; NC811's own pages would not open). Size: a notice may cover one parcel, or the lesser of five adjoining parcels or a quarter mile, and only what can be finished in 28 days. Positive response (87-122(c)): confirm through the system that every operator has answered before you dig. If one has not, you may go ahead only if there are no visible signs of a line (pole, marker, pedestal, meter, valve). If there are signs, send an additional notice; the operator must mark \"within three hours from the time the additional notice is received.\" You may start before the 3 days are up only when all operators have already answered. Design notice (87-127): operators answer within 10 working days; it \"may not be used for excavation purposes.\" Underwater (subaqueous) lines: 10 to 20 full working days' notice.", "source": "N.C.G.S. 87-117, 87-120 to 87-127, 87-129 (Article 8A, as amended by S.L. 2025-21); Norfield CENTER LOGiX \"Types of Tickets\" help page", "url": "https://www.ncleg.net/EnactedLegislation/Statutes/HTML/ByArticle/Chapter_87/Article_8A.html", "checked": "2026-11-20", "edition": "Statute as amended by Session Law 2025-21", "confidence": "high", "kind": "summary", "license": "gov-state"},
{"id": "dig-ny-marks-1", "state": "NY", "tier": "shelf", "title": "New York 811: tolerance zone 2 feet, hand-dug test holes, 4-inch rule", "topic": "811 marks: tolerance zone, hand digging, white lining, positive response", "text": "New York tolerance zone (753-1.2): \"the distance of one-half of the known diameter plus two feet\" on either side of the designated center line; if the diameter is not known, two feet on either side. Verify before you dig (753-3.6): where the work area and tolerance zone overlap, you must verify \"the precise location, type, size, direction of run and depth\" of the line. Gas and liquid petroleum lines must be verified by hand-dug test holes \"at one or more points where the work area and tolerance zone overlap.\" Other lines: hand-dug test holes or another way the operator agrees to. Power equipment in the zone before that: only to remove pavement or masonry, \"but only to the depth of such pavement or masonry,\" unless the operator agrees in writing. After the line is verified, no power equipment \"closer than four inches in any direction\" from it unless the operator agrees in writing (753-3.8). White (753-3.2): you \"shall delineate the work area with white paint, white stakes or other white suitable markings\" when needed to identify it. Colors (753-4.7): yellow gas and petroleum; red electric; orange communications; blue water; green sewer; purple reclaimed water; pink survey; white the excavation site.", "source": "16 NYCRR Part 753 (DPS booklet; Part 753 dated Feb 21, 2023); Gen. Bus. Law 765 (May 9, 2025)", "url": "https://dps.ny.gov/system/files/documents/2025/06/ss753-booklet-2025.05.09-update.pdf", "checked": "2026-11-20", "edition": "Part 753 as of February 21, 2023; booklet updated May 9, 2025", "confidence": "high", "kind": "summary", "license": "gov-state"},
{"id": "dig-pa-tickets-1", "state": "PA", "tier": "shelf", "title": "Pennsylvania 811: notice 3 to 10 business days, no-response rule, complex projects", "topic": "811 tickets: types, ticket life, renewals and updates", "text": "Pennsylvania notice (73 P.S. 180(2.1)): \"not less than three nor more than ten business days in advance of beginning excavation or demolition work.\" A business day is any day but Saturday, Sunday or a legal holiday, midnight to midnight. The lawful start date is the scheduled start date on the ticket. The statute sets no ticket life in days; it is not confirmed here. It does require a new notice if you vacate the worksite for more than two business days without other arrangements with the facility owners (clause 14). No response: if a facility owner \"fails to respond to the excavator's timely request,\" the excavator may proceed, not before the lawful start date and using due care (clause 5). PA One Call's response system (KARL) shows each owner's code, such as \"001 Clear\" and \"003 Field Marked\"; \"999 Did not respond\" is a violation by the owner. Find an unmarked or wrongly marked line when you arrive: renotify PA One Call; if the owner gives nothing useful within three hours you may proceed with care (clause 20). Complex projects (more than one locate request, or long schedules): a complex project ticket needs 10 business days' notice and a preconstruction meeting; they are entered through Coordinate PA, as are design notifications.", "source": "73 P.S. 176, 180, 182.10 (Underground Utility Line Protection Law; FindLaw copy, current as of Jan 1, 2026); PA One Call presentation to the PUC (Sept 2025)", "url": "https://codes.findlaw.com/pa/title-73-ps-trade-and-commerce/pa-st-sect-73-180/", "checked": "2026-11-20", "edition": "Current as of January 1, 2026", "confidence": "medium", "kind": "summary", "license": "gov-state", "unconfirmed": "ticket life in days"},
{"id": "dig-nm-damage-1", "state": "NM", "tier": "shelf", "title": "New Mexico 811: no-response, 18 inches, line hits, emergency locates", "topic": "811 emergencies and what to do when a line is hit", "text": "New Mexico rules on site (18.60.5.15 and .16 NMAC): before you dig, determine that all lines have been marked or cleared. If an operator has not marked or given a positive response, call for a warning locate; operators should respond \"ideally within two hours.\" The rule does not say you may dig without a response. Within \"18 inches either side of a marking made by a UFO\" (an operator), expose the line \"by non-mechanical means or mechanical vacuum excavation methods\" before machine work. Potholing or vacuum work done only to expose or find lines does not itself need a locate request. Damage: \"stop excavating immediately,\" call 911 if appropriate, the operator and 811, and secure the site. Do not \"leave the scene until authorized\" by an emergency responder or the operator, unless you tried and could not reach them and the site is secured. Emergency locates are marked as soon as practical, ideally within 2 hours; the emergency notice is good until the emergency is over or 48 hours, whichever is longer. Commission staff can shut down a dig that is not in compliance. Willful violations carry the penalties in NMSA 62-14-8; amounts were not confirmed. Design and bid locates are separate ticket types; no relocates or extensions on them.", "source": "18.60.5 NMAC sections 7, 8, 10, 11, 12, 13, 15, 16, 17 (Public Regulation Commission, srca.nm.gov)", "url": "https://www.srca.nm.gov/parts/title18/18.060.0005.html", "checked": "2026-11-20", "edition": "18.60.5 NMAC as posted Nov 20, 2026", "confidence": "medium", "kind": "summary", "license": "gov-state", "unconfirmed": "penalty amounts (NMSA 62-14-8)"},
{"id": "std-onecall-winter-snow-1", "state": "US", "tier": "shelf", "title": "811 in winter: snow, frozen ground and locate marks", "topic": "Locate marks: winter, snow and bad weather", "text": "Snow and frozen ground do not suspend the dig law anywhere: you still need a ticket, the wait, and marks you can see before a machine goes in. White marks do not show on snow. Several one-call rules name another color for the excavator's pre-marks when snow is on the ground, and it is not the same everywhere: check your state's rule before you mark. Marks buried by snow, plowed off or washed out are \"no longer visible\" under every law read: stop in that area and call 811 for a remark, and allow the normal re-mark time. Protect marks with stakes or flags next to the paint when snow is coming, and take photos of the marks the day they go down. Operators may get more time to mark in bad weather under some state laws, but they have to say so before the deadline; check positive response instead of assuming. Frozen ground is not a reason to skip potholing. Hand tools, air or hot-water vacuum still have to find the line inside the tolerance zone before the bucket or a frost ripper works there. Examples from the laws and handbooks read on Nov 20, 2026: Illinois law and the Alaska handbook say black when snow is on the ground; the Dig Safe manual for New England recommends fluorescent pink; Georgia and South Carolina list ice and snow as extraordinary circumstances that let an operator post a later marking date; Louisiana extends the mark-by time for inclement weather.", "source": "State one-call laws and 811 center handbooks read Nov 20, 2026: 220 ILCS 50/10; AK handbook p. 3; Dig Safe manual p. 9; O.C.G.A. 25-9-3(17); SC811 manual p. 20; La. R.S. 40:1749.14(C)(3)", "url": "https://ilga.gov/legislation/ilcs/ilcs3.asp?ActID=1286", "checked": "2026-11-20", "edition": "Sources as read November 20, 2026", "confidence": "medium", "kind": "summary", "license": "summary"},
{"id": "osha-pl-heat-proposed-1", "state": "US", "tier": "shelf", "title": "What the proposed federal heat rule would require (not in force)", "topic": "Heat illness rules", "text": "OSHA's 2024 proposal, not in force, would add 29 CFR 1926.67 for construction, the same text as proposed 1910.148. Initial heat trigger: a heat index of 80 F (or a wet bulb globe temperature at the NIOSH alert limit): drinking water at 1 quart per employee per hour, a shaded or air-conditioned break area, paid rest breaks as needed, two-way communication, and acclimatization for new workers (for example 20, 40, 60 and 80 percent of a normal shift on days 1 to 4) and for workers back after more than 14 days away (50, 60, 80 percent on days 1 to 3). High heat trigger: a heat index of 90 F: a paid 15-minute rest break at least every two hours, a buddy system or a supervisor watching no more than 20 employees, and a hazard alert. A written plan would be required for employers with more than 10 employees, with a named heat safety coordinator. Exposure of 15 minutes or less in any 60 minutes would be exempt. None of this is enforceable until a final rule is published.", "source": "OSHA proposed rule text (NPRM published 2024-08-30), proposed 29 CFR 1910.148 and 1926.67", "url": "https://www.osha.gov/sites/default/files/Heat-NPRM-Final-Reg-Text.pdf", "checked": "2026-11-20", "edition": "Proposed rule text, 2024; read 2026-11-20", "confidence": "high", "kind": "summary", "license": "gov-us"},
{"id": "osha-pl-record-forms-1", "state": "US", "tier": "shelf", "title": "OSHA 300, 300A and 301: who keeps them and the dates", "topic": "Injury reporting and OSHA recordkeeping", "text": "29 CFR Part 1904. Employers with 10 or fewer employees at all times during the last calendar year do not have to keep the OSHA injury and illness records unless OSHA or the Bureau of Labor Statistics tells them to in writing (1904.1); construction is not one of the low-hazard industries exempt under 1904.2. Covered employers enter each recordable case on the OSHA 300 log and a 301 incident report within 7 calendar days of learning of it (1904.29). The OSHA 300A annual summary is certified by a company executive and posted from February 1 to April 30 of the following year (1904.32). The log, summary and incident reports are kept for 5 years (1904.33). Larger establishments also send 300A data to OSHA electronically each year (1904.41). Reporting a death, hospitalization, amputation or eye loss (1904.39) applies to every employer, with or without a log. These sections were not checked against the rule text on 2026-11-20, so the numbers here are unconfirmed until they are read; state plans may also require records from smaller employers.", "source": "29 CFR 1904.1, 1904.2, 1904.29, 1904.32, 1904.33, 1904.41", "url": "https://www.osha.gov/laws-regs/regulations/standardnumber/1904/", "checked": "2026-11-20", "edition": "29 CFR Part 1904 (not re-read 2026-11-20)", "confidence": "medium", "kind": "summary", "license": "gov-us", "unconfirmed": "yes"},
{"id": "osha-pl-health-lead-1", "state": "US", "tier": "shelf", "title": "Lead in construction: the OSHA limits", "topic": "Jobsite health: first aid, water, toilets, noise", "text": "29 CFR 1926.62 covers lead in construction, which a pipe crew can meet when cutting or burning old lead-jointed cast iron pipe, lead service lines, lead paint on steel, or lead-sheathed cable. The permissible exposure limit is 50 micrograms per cubic meter of air as an 8-hour average and the action level is 30. Until the employer has measured exposure, certain tasks are treated as over the limit and need respirators, protective clothing, change areas, hand washing, blood tests and training. Do not eat, drink or smoke in the work area, and wash before breaks. The numbers in this card were not checked against the rule text on 2026-11-20, so read the section before you rely on them.", "source": "29 CFR 1926.62(b), (c), (d)", "url": "https://www.ecfr.gov/current/title-29/section-1926.62", "checked": "2026-11-20", "edition": "29 CFR text (not re-read 2026-11-20)", "confidence": "medium", "kind": "summary", "license": "gov-us", "unconfirmed": "yes"},
{"id": "osha-pl-fire-1", "state": "US", "tier": "shelf", "title": "Fire extinguishers and fuel on a construction site", "topic": "Other OSHA construction rules", "text": "29 CFR 1926.150 and 1926.152. A fire extinguisher rated at least 2A is provided for each 3,000 square feet of protected building area, with travel distance to the nearest one not over 100 feet. At least one extinguisher rated 10B or higher is within 50 feet of any place where more than 5 gallons of flammable or combustible liquid or 5 pounds of flammable gas is used. Flammable liquids are kept in approved containers; safety cans for quantities of 5 gallons or less. Fueling: shut the engine off, no smoking or open flame, and keep an extinguisher at the fuel service area. Extinguishers are inspected and kept in working order. The numbers in this card were not checked against the rule text on 2026-11-20, so read the section before you rely on them.", "source": "29 CFR 1926.150(c)(1); 1926.152(a), (g)", "url": "https://www.ecfr.gov/current/title-29/section-1926.150", "checked": "2026-11-20", "edition": "29 CFR text (not re-read 2026-11-20)", "confidence": "medium", "kind": "summary", "license": "gov-us", "unconfirmed": "yes"},
{"id": "osha-pl-elec-gfci-1", "state": "US", "tier": "shelf", "title": "GFCI protection for cords and tools on a jobsite", "topic": "Electrical safety and lockout", "text": "29 CFR 1926.404(b)(1): the employer uses either ground-fault circuit interrupters or an assured equipment grounding conductor program to protect employees. With GFCIs, all 120-volt, single-phase, 15- and 20-ampere receptacle outlets on construction sites that are not part of the permanent wiring have approved GFCI protection. That covers generators, pumps, saws and lights run from temporary power; small portable generators of 5 kW or less with a two-wire ungrounded system are an exception in the rule. The other option is a written assured equipment grounding program with a competent person, visual inspection of cords before each day's use, and periodic continuity tests. The numbers in this card were not checked against the rule text on 2026-11-20, so read the section before you rely on them.", "source": "29 CFR 1926.404(b)(1)(i)-(iii)", "url": "https://www.ecfr.gov/current/title-29/section-1926.404", "checked": "2026-11-20", "edition": "29 CFR text (not re-read 2026-11-20)", "confidence": "medium", "kind": "summary", "license": "gov-us", "unconfirmed": "yes"},
{"id": "osha-pl-scaffold-1", "state": "US", "tier": "shelf", "title": "Scaffolds in brief: the numbers a pipe crew meets", "topic": "Other OSHA construction rules", "text": "29 CFR 1926 Subpart L (1926.450 to 1926.454). A scaffold carries its own weight plus at least 4 times the maximum intended load. Fall protection on a scaffold is required at more than 10 feet above a lower level, not 6 feet. A competent person inspects the scaffold before each work shift and after anything that could affect it, and scaffolds are erected, moved and taken down only under a competent person. Access by ladder, stair tower or ramp is needed when the platform is more than 2 feet above or below the access point. Inside a deep structure or wet well a scaffold is also inside a confined space, and both rules apply. The numbers in this card were not checked against the rule text on 2026-11-20, so read the section before you rely on them.", "source": "29 CFR 1926.451(a)(1), (e)(1), (f)(3), (f)(7), (g)(1)", "url": "https://www.ecfr.gov/current/title-29/section-1926.451", "checked": "2026-11-20", "edition": "29 CFR text (not re-read 2026-11-20)", "confidence": "medium", "kind": "summary", "license": "gov-us", "unconfirmed": "yes"},
{"id": "osha-pl-crane-basics-1", "state": "US", "tier": "shelf", "title": "Cranes on a pipe job: operator, signal person and keeping clear", "topic": "Equipment, vehicles, rigging and cranes", "text": "29 CFR 1926 Subpart CC applies when a crane, boom truck or similar hoisting machine sets structures, vaults, pipe or trench boxes. The operator is trained, certified or licensed, and evaluated by the employer on the machine (1926.1427). A signal person is needed when the point of operation is not in full view of the operator, when the view is blocked in the direction of travel, or when the operator or the person handling the load sees a need (1926.1419), and signal persons are qualified (1926.1428). Riggers are qualified. Hoisting routes that keep loads from passing over people are used where possible, and people stay out of the fall zone except those hooking, unhooking or guiding the load (1926.1425). A competent person inspects the crane each shift. Excavators and backhoes are excluded from Subpart CC. The numbers in this card were not checked against the rule text on 2026-11-20, so read the section before you rely on them.", "source": "29 CFR 1926.1419(a), 1926.1425, 1926.1427, 1926.1428, 1926.1412", "url": "https://www.ecfr.gov/current/title-29/section-1926.1427", "checked": "2026-11-20", "edition": "29 CFR text (not re-read 2026-11-20)", "confidence": "medium", "kind": "summary", "license": "gov-us", "unconfirmed": "yes"},
{"id": "osha-pl-concrete-1", "state": "US", "tier": "shelf", "title": "Rebar caps and concrete work rules", "topic": "Other OSHA construction rules", "text": "29 CFR 1926 Subpart Q. 1926.701(b): all protruding reinforcing steel, onto and into which employees could fall, is guarded to eliminate the hazard of impalement; ordinary small plastic mushroom caps do not stop impalement from a fall, so use caps or troughs made for it or bend the bars over. No employee works under concrete buckets while they are being raised or lowered into position. 1926.703: formwork is designed and braced to carry all loads, and forms and shores are not removed until the concrete can support its weight. 1926.704: precast pieces such as manhole sections, vaults and box culverts are supported so they cannot tip over or collapse until permanently connected, and no one is under a precast piece being lifted or tilted into position unless needed for the erection. The numbers in this card were not checked against the rule text on 2026-11-20, so read the section before you rely on them.", "source": "29 CFR 1926.701(b), (e); 1926.703(a), (e); 1926.704(a), (e)", "url": "https://www.ecfr.gov/current/title-29/section-1926.701", "checked": "2026-11-20", "edition": "29 CFR text (not re-read 2026-11-20)", "confidence": "medium", "kind": "summary", "license": "gov-us", "unconfirmed": "yes"},
{"id": "osha-pl-tunnel-1", "state": "US", "tier": "shelf", "title": "Tunnels, shafts and jacked pipe: when OSHA Subpart S applies", "topic": "Other OSHA construction rules", "text": "29 CFR 1926.800 covers the construction of underground tunnels, shafts, chambers and passageways, and cut-and-cover excavations that are connected to ongoing underground construction or that create conditions like underground construction. Work under Subpart S is outside the confined space rule (1926.1201(b)). Key duties: a check-in and check-out procedure so the surface knows who is underground; at least one designated person on duty above ground who can summon help; a competent person who tests the air as often as needed (oxygen at least 19.5 percent, and limits on flammable gas, carbon monoxide and hydrogen sulfide); mechanical ventilation; a classification as potentially gassy or gassy when methane is found; rescue teams or services arranged in advance; and emergency lighting for each person underground. Large-diameter jacking and microtunnel shafts and tunnels that people enter usually fall here, not under the trench rule. The numbers in this card were not checked against the rule text on 2026-11-20, so read the section before you rely on them.", "source": "29 CFR 1926.800(a), (c), (g), (j), (k)", "url": "https://www.ecfr.gov/current/title-29/section-1926.800", "checked": "2026-11-20", "edition": "29 CFR text (not re-read 2026-11-20)", "confidence": "medium", "kind": "summary", "license": "gov-us", "unconfirmed": "yes"},
{"id": "osha-pl-asbestos-pipe-1", "state": "US", "tier": "shelf", "title": "Asbestos cement (transite) pipe: the OSHA rule", "topic": "Other OSHA construction rules", "text": "29 CFR 1926.1101 covers asbestos in construction, including cutting, tapping, removing or repairing asbestos cement (AC, transite) water and sewer pipe. The permissible exposure limit is 0.1 fiber per cubic centimeter of air as an 8-hour average, with an excursion limit of 1.0 fiber over 30 minutes. Work on AC pipe is supervised by a competent person, uses wet methods and tools that do not make dust (snap cutters, wet hand tools; no dry abrasive saw cutting), and is done by trained workers. Waste pipe is kept wet, wrapped or bagged and labeled. State and local air rules and the owner's specifications often add notice and disposal steps. The numbers in this card were not checked against the rule text on 2026-11-20, so read the section before you rely on them.", "source": "29 CFR 1926.1101(c), (g), (k), (o)", "url": "https://www.ecfr.gov/current/title-29/section-1926.1101", "checked": "2026-11-20", "edition": "29 CFR text (not re-read 2026-11-20)", "confidence": "medium", "kind": "summary", "license": "gov-us", "unconfirmed": "yes"},
{"id": "mutcd-6a-principles-1", "state": "US", "tier": "shelf", "title": "MUTCD: the seven basic principles of temporary traffic control", "topic": "Traffic control: MUTCD basics and status", "text": "Section 6A.02 lists seven principles for every work zone. A, plan it: use the same safety thinking as a permanent road and have a traffic control plan that everyone understands before you occupy the road. B, slow traffic down as little as practical: drivers only slow when they see a clear need, so avoid abrupt changes, keep closures short and off-peak, and keep a path for bikes and pedestrians, including people with disabilities. C, guide drivers clearly: enough warning, delineation and channelizing, and cover or remove signs and markings that no longer apply. D, inspect: a knowledgeable person checks the setup day and night, changes it as the work changes, and can stop work until it is fixed. E, keep the roadside safe: crashworthy devices, and store equipment, trucks, materials and spoil where a car is not likely to hit them. F, train everyone whose decisions affect work zone safety, and only trained people supervise the choice and placement of devices. G, tell the public, the neighbors, emergency services and schools ahead of time. The same section says safety of road users and workers should be a high priority from planning through construction. Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Section 6A.02 paras. 1-2 (items A-G)", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"},
{"id": "mutcd-6b-detour-1", "state": "US", "tier": "shelf", "title": "Detour or diversion: the difference", "topic": "Traffic control: parts of a work zone", "text": "A detour sends road users onto another existing road to get around the work zone. A diversion sends them onto a temporary road or temporary alignment built around the work area, inside or next to the right-of-way (Section 6B.09). A detour should be signed over its whole length so drivers can get back to the road they were on. On a long detour, repeat the Detour signs so drivers know they are still on it (Section 6N.09). When a whole road is closed, warn drivers ahead of the last place they can turn off, and where local traffic can still reach homes and businesses use ROAD CLOSED AHEAD, LOCAL TRAFFIC ONLY. When the road is legally closed but local access stays open, the barricades usually do not span the full road and a sign has to state the permitted local access (Section 6K.07). Type 3 barricades are the device for a full or partial road closure. Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Sections 6B.09, 6N.09 paras. 2-5, 6K.07 paras. 18-22", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"},
{"id": "mutcd-6g-finesigns-1", "state": "US", "tier": "shelf", "title": "Work zone speed limit and higher fines signs", "topic": "Traffic control: advance warning signs", "text": "The MUTCD has the signs; the fine itself comes from state law. A WORK ZONE plaque (G20-5aP) may go above a Speed Limit sign, and an END WORK ZONE SPEED LIMIT sign (R2-12) may mark the end. Where higher fines apply, a BEGIN HIGHER FINES ZONE sign (R2-10) should be placed at or near the start of the zone and END HIGHER FINES ZONE (R2-11) at the end; the legend may say DOUBLE FINES instead, and a FINES HIGHER, FINES DOUBLE or dollar amount plaque may go under the Speed Limit sign (Section 6G.08). Many state laws only double the fine when these signs are up and workers are present, so missing signs can cost the enforcement. On speed limits themselves, Section 6B.01 says reduced speed zoning should be avoided as much as practical, kept to a 10 mph reduction or less where used, and placed only where there is a restrictive feature; a drop of more than 10 mph needs extra notice and a step-down. Only the agency with authority over the road can set a regulatory work zone speed limit. Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Section 6G.08 paras. 1-5; Table 6G-1; Section 6B.01 paras. 17-20", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"},
{"id": "mutcd-6k-peddevices-1", "state": "US", "tier": "shelf", "title": "Pedestrian channelizing devices: the cane-detectable barricade", "topic": "Traffic control: pedestrians and sidewalks", "text": "When work affects a sidewalk, pedestrian channelizing devices should be used to close it and to mark the temporary route (Section 6K.02). Requirements (Standard): devices that channel pedestrians shall be detectable to a person using a long cane and visible to people with low vision; used as a sidewalk closure, the device shall cover the whole width of the sidewalk; exposed to traffic, it shall be crashworthy. The device has a continuous detection plate at the bottom and a continuous hand-trailing edge at the top, in the same vertical plane: bottom of the plate no more than 2 inches above the walk, top of the plate at least 8 inches above it, and the top of the hand-trailing edge between 32 and 38 inches. Gaps between devices in a run should not be more than 1 inch. Where a continuous wall is used instead, its bottom edge is no more than 2 inches up and it reaches at least 32 inches. Barricade rail supports should not stick out more than 4 inches into the walking route between 27 and 80 inches above the surface (Section 6K.07). Cones with caution tape do not meet this. Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Section 6K.02 paras. 2-19; Section 6K.07 paras. 10-11; Figure 6K-2", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"},
{"id": "mutcd-6l-lights-1", "state": "US", "tier": "shelf", "title": "Warning lights and message signs in a work zone", "topic": "Traffic control: cones, drums, barricades and arrow boards", "text": "Warning lights (Section 6L.07) are yellow. Type A is a low-intensity flashing light for night, used on barricades and signs that warn of a hazard. Type B is a high-intensity flashing light for day and night, used on advance warning signs or its own support. Type C and Type D (360 degree) are steady-burn lights used in a row to show the edge of the traveled way at night. Rules (Standard): a light on a device used alone to warn shall flash; lights on a series of channelizing devices shall be steady-burn, except sequential lights in a merging taper, which flash in order from upstream to downstream; flashing lights shall not be used for delineation; the bottom of the lens is at least 30 inches high. Type A, C and D lights are visible from 3,000 ft on a clear night; Type B from 1,000 ft on a sunny day. Portable changeable message signs (Section 6L.05): should be readable from half a mile, with letters at least 18 inches tall, no more than two phases of three lines each, and should sit off the shoulder or behind barrier where practical; the bottom is at least 7 ft above the road in urban areas and 5 ft in rural areas. A flag tree (high-level warning device) has at least two flags and is meant to be seen over cars (Section 6L.08). Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Sections 6L.05 paras. 11-30, 6L.07 paras. 3-20, 6L.08 paras. 1-3", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"},
{"id": "mutcd-6l-afad-1", "state": "US", "tier": "shelf", "title": "Automated flagger assistance devices (AFAD)", "topic": "Traffic control: flaggers", "text": "An AFAD lets the flagger stand out of the lane and run a remote STOP/SLOW sign or a red/yellow light with a gate arm. Rules from Sections 6L.02 to 6L.04 (Standard): an AFAD shall be used only where there is one lane of approaching traffic to control; it shall be operated only by a flagger trained on that device, who shall not leave it unattended while it is in use; at night its location is lit like a flagger station. Two flaggers are used with the usual two methods of operation, unless one flagger has a clear view of both devices and of traffic from both directions. A STOP/SLOW AFAD has a sign at least 24 by 24 inches with letters at least 8 inches high, mounted with the bottom at least 6 ft above the pavement, and a WAIT ON STOP sign (R1-7) faces approaching drivers. A red/yellow lens AFAD has 12 inch circular red and yellow lenses and a STOP HERE ON RED sign on the right side of the approach. Advance signs should include ROAD WORK AHEAD and ONE LANE ROAD. Some states require the AFAD operator to hold the state's flagger card. Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Sections 6L.02 paras. 4-15, 6L.03 paras. 2-12, 6L.04 paras. 2-5", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"},
{"id": "mutcd-6m-barrier-1", "state": "US", "tier": "shelf", "title": "Temporary traffic barrier (K-rail) in a work zone", "topic": "Traffic control: cones, drums, barricades and arrow boards", "text": "Temporary traffic barrier keeps vehicles out of the work space; cones, drums and water-filled channelizers do not. Section 6M.02: the decision to use barrier is based on engineering judgment, looking at how close traffic is, its speed, the duration, and what is behind the line, such as an open trench or workers on foot. Requirements (Standard): temporary barrier, including the end treatment, shall be crashworthy; it shall be supplemented with delineation, pavement markings or channelizing devices so drivers can see it day and night; and short, separated pieces of barrier shall not be used, because gaps cancel the protection and create blunt ends. Steady-burn warning lights may be mounted on it. Where a pedestrian route runs close to traffic, the two should be separated with temporary traffic barrier, and ordinary vertical curb shall not be used in place of barrier where barrier is needed (Section 6C.02). Barrier deflects when hit, so leave room behind it. Positive protection may be added to any of the typical applications. Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Section 6M.02 paras. 7-11; Section 6C.02 paras. 20-23", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"},
{"id": "mutcd-6p-ta6-1", "state": "US", "tier": "shelf", "title": "TA-6: shoulder work that takes a little of the lane", "topic": "Traffic control: typical setups for utility work", "text": "TA-6 is for work on the shoulder that sticks a short way into the travel lane on a low-speed minor road. Notes: every lane left open should be at least 10 ft wide, measured to the near face of the cones (Guidance). For short-term work on a low-volume, low-speed road with no long or wide trucks, 9 ft may be used. If you cannot keep that width, or speeds are higher, close the lane instead. If the far shoulder is good and wide enough, the lanes may be shifted over with closely spaced devices, keeping 10 ft. A ROAD NARROWS sign may be added. A shadow vehicle sits upstream of the work; it may be left out if a taper and cones are used, and it may carry a truck-mounted attenuator. For short-duration work the taper and cones may be left out if a shadow vehicle with activated high-intensity lights is used. Shadow and work vehicles shall show high-intensity rotating, flashing, oscillating or strobe lights, and four-way flashers shall not be used in their place (Standard). Vehicle-mounted signs must not be blocked by equipment and are covered or turned when work is not in progress. Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Figure 6P-6 (TA-6) notes 1-14; Section 6N.07", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"},
{"id": "mutcd-6p-ta11-1", "state": "US", "tier": "shelf", "title": "TA-11, TA-13 and TA-18: low-volume roads, brief road closure, minor street", "topic": "Traffic control: typical setups for utility work", "text": "TA-11, lane closure on a two-lane road with low traffic volume: STOP or YIELD sign control may replace flaggers when traffic is light enough that drivers who must yield get gaps, and drivers from both ends can see through and beyond the work. Type B flashing lights may go on the ROAD WORK AHEAD and ONE LANE ROAD AHEAD signs for a night closure. TA-13, temporary road closure: for a planned full stop of no more than 20 minutes in the daytime, for example to set a structure or swing a load. A flagger or a uniformed officer shall be used (Standard); a BE PREPARED TO STOP sign may be added ahead of the Flagger sign. TA-18, lane closure on a minor street: only for low-speed streets with low volume (Standard). Where the work space is short and drivers can see through, traffic may regulate itself; where it cannot, one or two flaggers shall be used as in TA-10 (Standard). Flashing lights or flags may be put on the advance signs, and a truck-mounted attenuator may be used on the work or shadow vehicle. Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Figures 6P-11 (TA-11) notes 2-3, 6P-13 (TA-13) notes 1-7, 6P-18 (TA-18) notes 1-6", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"},
{"id": "mutcd-6p-ta15-1", "state": "US", "tier": "shelf", "title": "TA-15 and TA-26: work in the center of the road or the middle of an intersection", "topic": "Traffic control: typical setups for utility work", "text": "TA-15, work in the center of a low-volume road (a manhole in the centerline, for example): traffic passes on both sides. The lane on each side should be at least 10 ft wide, measured from the near edge of the cones to the edge of pavement or the outside edge of a paved shoulder; 9 ft may be used for short-term work on low-volume, low-speed roads without long or wide trucks. A work vehicle with activated high-intensity flashing lights may take the place of the cones in the tapers or of the flag tree. Warning lights may go on the cones if the closure stays overnight. TA-26, closure in the center of an intersection: all lanes at least 10 ft wide to the near face of the cones (9 ft on the same short-term, low-speed, low-volume condition). A flag tree may be set in the work space. Left turns may be prohibited where the geometry will not let large vehicles make them. For short-duration work the cones may be left out if a vehicle with activated high-intensity lights is in the work space. In both, four-way hazard flashers may be added but shall not replace the high-intensity lights (Standard). Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Figures 6P-15 (TA-15) notes 1-8, 6P-26 (TA-26) notes 1-8", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"},
{"id": "mutcd-6p-ta21-1", "state": "US", "tier": "shelf", "title": "TA-21, TA-22, TA-23 and TA-27: lane closures at an intersection", "topic": "Traffic control: typical setups for utility work", "text": "TA-21, near side: the merging taper shall direct traffic into either the right lane or the left lane, but not both (Standard). A left taper keeps right turns from holding up through traffic. A shadow vehicle with a truck-mounted attenuator may be used. TA-22, right lane closed on the far side: if the right lane carries a lot of right turns, the approach lane may be kept for right turns only, pushing through traffic to the left lane; where the approach is down to one lane, left turns may be prohibited to keep through traffic moving. TA-23, left lane closed on the far side: the left lane may reopen as a left-turn-only bay so turning cars do not block through traffic. TA-27, closure at the side of an intersection: flaggers or uniformed officers should direct traffic inside the intersection; ONE LANE ROAD AHEAD signs should be used, a BE PREPARED TO STOP sign goes ahead of the Flagger sign if used, and flagger stations shall be lit at night (Standard). The simplest fix is often to close one approach or send through traffic another way. In all of them: if the work space crosses a crosswalk, close the crosswalk as TA-29 shows. Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Figures 6P-21 notes 1-9, 6P-22 notes 1-8, 6P-23 notes 1-5, 6P-27 notes 1-12", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"},
{"id": "mutcd-6p-multilane-1", "state": "US", "tier": "shelf", "title": "TA-30, TA-33 and TA-35: lane closures on multi-lane roads", "topic": "Traffic control: typical setups for utility work", "text": "TA-30, interior lane closure on a multi-lane street: for low-speed, low-volume city streets; where speed or volume is higher add signs such as LEFT LANE CLOSED with the distance between the signs shown. Closing the inside lane of the opposite direction may not be needed. TA-33, stationary lane closure on a divided highway: lane closed signs and lane ends signs, a full merging taper of length L, a buffer, cones along the work and a downstream taper. When a shoulder 8 ft or wider is closed, cones should close the shoulder ahead of the merging taper. If a side road enters inside the zone, add devices for it (Standard). An arrow board shall be used when a freeway lane is closed, one board for each closed lane (Standard). TA-35, mobile operation on a multi-lane road: arrow boards shall be at least Type B, 60 by 30 inches; shadow and work vehicles shall show high-intensity flashing lights (Standard). The first shadow vehicle should carry an arrow board and a truck-mounted attenuator; keep the gaps between vehicles short so drivers do not cut in; work off-peak. Truck-mounted attenuators and other positive protection may be added to any of these. Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Figures 6P-30 notes 1-4, 6P-33 notes 1-7, 6P-35 notes 1-15", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"},
{"id": "mutcd-6p-ta17-1", "state": "US", "tier": "shelf", "title": "TA-17: mobile operation on a two-lane road", "topic": "Traffic control: short jobs and mobile work", "text": "TA-17 covers work that keeps moving on a two-lane road, with a work vehicle and a shadow vehicle behind it. Standard notes: vehicle-mounted signs shall be mounted so equipment or supplies do not hide them, and are covered or turned from view when work is not in progress; shadow and work vehicles shall display high-intensity rotating, flashing, oscillating or strobe lights; if an arrow board is used it shall be in caution mode; four-way flashers shall not be used in place of the high-intensity lights. Guidance: where practical the vehicles should pull over from time to time to let traffic by; the shadow vehicle should hold a steady distance behind the work vehicle and drop back before curves and hill crests so drivers coming from behind see it in time; the shadow vehicle should have two high-intensity flashing lights on the rear next to the sign. Options: more shadow vehicles, a truck-mounted attenuator on the shadow or work vehicle, and a DO NOT PASS sign on the rear of the blocking vehicle where the vehicles cannot pull over often. Your state manual and the approved traffic control plan or permit govern on the job.", "source": "MUTCD 11th Edition (FHWA, Dec 2023; Rev. 1 Dec 2025), Part 6, Figure 6P-17 (TA-17) notes 1-13", "url": "https://mutcd.fhwa.dot.gov/pdfs/11th_Edition/part6.pdf", "checked": "2026-11-20", "edition": "11th Edition, December 2023 (Revision 1, December 2025)", "effective": "2024-01-18", "confidence": "high", "kind": "summary", "license": "gov-us"},
{"id": "tc-ca-buffer-1", "state": "CA", "tier": "shelf", "title": "California buffer space and flagger distance, including downgrades (Table 6B-2(CA))", "topic": "Traffic control: tapers and buffer spaces", "text": "California's CA MUTCD 2026 uses the national stopping sight distance table for a longitudinal buffer space or a flagger station on a level road, and adds Table 6B-2(CA) for downgrades. Level road (Table 6B-2): 25 mph 155 ft, 30 mph 200 ft, 35 mph 250 ft, 40 mph 305 ft, 45 mph 360 ft, 50 mph 425 ft, 55 mph 495 ft, 60 mph 570 ft, 65 mph 645 ft. Downgrades, as minus 3 percent, minus 6 percent, minus 9 percent: 25 mph 158, 165, 173 ft. 30 mph 205, 215, 227 ft. 35 mph 257, 271, 287 ft. 40 mph 315, 333, 354 ft. 45 mph 378, 400, 427 ft. 50 mph 446, 474, 507 ft. 55 mph 520, 553, 593 ft. 60 mph 598, 638, 686 ft. 65 mph 682, 728, 785 ft. Using the table for a buffer is an Option in Section 6B.06; no work, equipment, vehicles or material should be in the buffer. Flagger stations may be placed with the same distances and shall be lit at night except in emergencies (Section 6D.06).", "source": "CA MUTCD 2026, Section 6B.06 para. 11; Tables 6B-2 and 6B-2(CA); Section 6D.06 paras. 3, 5", "url": "https://dot.ca.gov/-/media/dot-media/programs/safety-programs/documents/ca-mutcd/2026/2026-camutcd-2026-6b-a11y.pdf", "checked": "2026-11-20", "confidence": "high", "kind": "summary", "license": "summary", "edition": "CA MUTCD 2026", "effective": "2026-01-18"},
{"id": "tc-ca-plans-1", "state": "CA", "tier": "shelf", "title": "California Caltrans standard plans for traffic control (T-series)", "topic": "Traffic control: typical setups for utility work", "text": "California State highway work uses the Caltrans Standard Plans for traffic control systems, which the CA MUTCD 2026 points to as T9 through T27 (Section 6B.08). From the 2026 Standard Plans digest: T9 carries the advance warning sign spacing table; T10 is the lane closure plan and T10A the complete closure and lane closure with partial shoulder use; T11 is a typical lane closure and T11A a changeable lane closure; T12 is a half-road closure; T13 covers reversible (one-lane, two-way) traffic control with flaggers, with T13B for residential driveways and low-volume side roads; T14 covers ramps; T15 and T16 are moving lane closures on multilane highways. A Caltrans encroachment permit will name the T-plan to use. City and county streets follow the CA MUTCD and the city's own permit conditions; many cities accept a T-plan or a typical application as the traffic control plan for a short utility job. Sheet titles for T13, T13A, T13C and T17 were not confirmed from the digest.", "source": "CA MUTCD 2026 Section 6B.08 para. 16; Caltrans 2026 Standard Plans digest (T9-T17)", "url": "https://dot.ca.gov/-/media/dot-media/programs/design/documents/2026-standard-plans-digest-a11y.pdf", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "summary", "edition": "Caltrans 2026 Standard Plans", "unconfirmed": "yes"},
{"id": "tc-wa-flagger-2", "state": "WA", "tier": "shelf", "title": "Washington flagging: sign sequence, flagger station distance, apparel and lighting", "topic": "Traffic control: flaggers", "text": "Washington's flagger rule, WAC 296-155-305, sets numbers the national manual leaves open. Advance warning signs: a three-sign sequence on roads posted below 45 mph and a four-sign sequence at 45 mph or higher. Flagger station distance ahead of the work space (Table 2): 20 mph 35 ft, 25 mph 55 ft, 30 mph 85 ft, 35 mph 120 ft, 40 mph 170 ft, 45 mph 220 ft, 50 mph 280 ft, 55 mph 335 ft, 60 mph 415 ft, 65 mph 485 ft; longer is acceptable. Flaggers stand on the shoulder next to the traffic they control or in the closed lane, and step into the lane only after traffic has stopped. Flaggers must not be exposed to traffic or equipment coming from behind unless there is a way to warn them, such as an observer or a mirror. Apparel in daylight: a Class 2 high-visibility garment and a high-visibility hard hat. In darkness, from half an hour before sunset to half an hour after sunrise: the Class 2 garment plus white coveralls or trousers with reflective leg bands, and a hard hat with at least 12 square inches of reflective material. Flagger stations are lit with floodlights at night, set so they do not glare at drivers. Sign spacing by road type is in the rule's Table 1; those values were not confirmed row by row here, so read the table.", "source": "WAC 296-155-305(4), (5), (8), (9) and Tables 1 and 2", "url": "https://www.law.cornell.edu/regulations/washington/WAC-296-155-305", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "gov-state", "edition": "WAC 296-155-305, last amended WSR 16-09-085", "effective": "2016-05-20", "unconfirmed": "yes"},
{"id": "tc-or-taper-1", "state": "OR", "tier": "shelf", "title": "Oregon taper lengths and cone counts by speed (OTTCH Table 2-3)", "topic": "Traffic control: tapers and buffer spaces", "text": "Oregon's Temporary Traffic Control Handbook 2026 prints taper lengths with the number of cones in Table 2-3. Merging taper for a 12 ft lane: 25 mph 125 ft (6 cones), 30 mph 180 ft (7), 35 mph 245 ft (8), 40 mph 320 ft (9), 45 mph 540 ft (13), 50 mph 600 ft (13), 55 mph 660 ft (13), 60 mph 720 ft (13), 65 mph 780 ft (13). For an 11 ft lane: 25 mph 115 ft, 30 mph 165 ft, 35 mph 225 ft, 40 mph 295 ft, 45 mph 495 ft, 55 mph 605 ft. For a 10 ft lane: 25 mph 105 ft, 30 mph 150 ft, 35 mph 205 ft, 40 mph 270 ft, 45 mph 450 ft, 55 mph 550 ft. Shifting tapers are half: 12 ft at 35 mph is 125 ft, at 45 mph 270 ft. Shoulder taper (10 ft shoulder): 25 mph 35 ft, 35 mph 70 ft, 45 mph 150 ft, 55 mph 185 ft. The formulas are the national ones (Tables 2-1 and 2-2). One-lane two-way and downstream tapers are 50 to 100 ft with 4 to 6 cones at 20 ft. Night flagger stations: lit separately from the work, light 15 to 21 ft high on the flagger's side, at least 5 foot-candles, flagger recognizable from 1,000 ft (sections 3.8, 4.3). Sign spacing and buffer lengths are in Table 2-4; those values were not confirmed here because the table did not read cleanly.", "source": "Oregon Temporary Traffic Control Handbook 2026, Tables 2-1, 2-2, 2-3; sections 2.3, 3.8, 4.3", "url": "https://www.oregon.gov/odot/Engineering/Docs_TrafficEng/OTTCH-2026.pdf", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "summary", "edition": "OTTCH 2026 Edition, January 2026", "unconfirmed": "yes"},
{"id": "mfr-pvcpa-sewer-1", "state": "US", "tier": "shelf", "title": "PVC sewer pipe (SDR 35, SDR 26, ASTM D3034): installation basics from the PVC Pipe Association guide", "topic": "Pipe installation guides by material", "text": "PVC gravity sewer pipe installation, summarized from the Uni-Bell PVC Pipe Association guide for solid-wall PVC sewer pipe (PUB-06-25). Product standard is ASTM D3034; the guide notes that since 2024 D3034 covers 3 through 60 inch, so old references to ASTM F679 for 18 inch and up are being replaced. Common stiffness classes: DR 35 and DR 26 in 4 to 15 inch; PS 46, PS 75 and PS 115 in 18 to 60 inch. Installation practice is ASTM D2321. Nothing larger than 1-1/2 inches should touch the pipe. Bedding is typically 4 to 6 inches; dig bell holes only as big as needed; bring an over-dug bottom back to grade for the full length, not just at the bells. Haunching: work material under the haunches and at least halfway up the pipe and compact it (shovel slicing works). Initial backfill: at least 6 inches over the pipe, rock free, before any machine compaction over the top. Flotation: keep the trench dry until there is about 2 pipe diameters of backfill over thin-wall pipe (DR 32.5 and higher) or 1-1/2 diameters over heavier pipe. Joints: lubricate per the maker, push until the insertion line is even with the bell lip, and do not over-insert; re-bevel and re-mark field cuts. Bending: rule of thumb radius is 200 times the pipe OD, and bending pipe over 12 inch is not recommended; do not bend and deflect the joint on the same length. Acceptance: clean, then CCTV; a go/no-go mandrel sized for 7-1/2 percent deflection per D3034 (many specs require 5 percent); low-pressure air per ASTM F1417.", "source": "Uni-Bell PVC Pipe Association, Installation Guide for Solid-Wall PVC Sewer Pipe, PUB-06-25 (our summary; read 2026-11-20)", "url": "https://www.uni-bell.org/portals/0/resourcefile/installation-guide-for-solid-wall-pvc-sewer-pipe.pdf", "checked": "2026-11-20", "edition": "PUB-06-25", "confidence": "medium", "kind": "summary", "license": "summary"},
{"id": "mfr-dipra-install-1", "state": "US", "tier": "shelf", "title": "Ductile iron pipe: laying conditions Types 1 to 5, cover, trench width, polywrap (DIPRA guide)", "topic": "Pipe installation guides by material", "text": "Ductile iron pipe laying, summarized from the DIPRA Installation Guide for Ductile Iron Pipe (revised May 2015). Laying conditions (the trench types used in AWWA C150 and C600): Type 1 flat-bottom trench with loose backfill (not for 14 inch and larger); Type 2 flat-bottom trench, backfill lightly consolidated to the pipe centerline; Type 3 pipe bedded in at least 4 inches of loose soil, backfill lightly consolidated to the top of the pipe; Type 4 bedding of sand, gravel or crushed stone to 1/8 of the pipe diameter (4 inch minimum), backfill compacted to about 80 percent Standard Proctor; Type 5 bedded to the centerline in compacted granular material (4 inch minimum under the pipe), backfill compacted to about 90 percent Standard Proctor. The plans say which type. Cover is generally 2.5 to 3 feet minimum, deeper in frost country. Keep rock at least 6 inches away from pipe 24 inch and smaller and 9 inches from 30 inch and larger. Polyethylene encasement (AWWA C105) in corrosive soil: one tube per pipe length, overlapped about 1 foot at joints, taped at the ends and about every 2 feet, with slack at the joints; repair tears with tape. Before tapping polywrapped pipe, wrap 2 to 3 layers of tape around the pipe at the tap. Direct taps: 3/4 inch on all sizes, 1 inch on 6 inch and larger; bigger services need a saddle or tapping sleeve per the guide's table.", "source": "Ductile Iron Pipe Research Association (DIPRA), Installation Guide for Ductile Iron Pipe, revised May 2015, hosted by McWane (our summary; read 2026-11-20)", "url": "https://pe.mcwane.com/upl/downloads/dipra/dip-installation-guide-ab36416e.pdf", "checked": "2026-11-20", "edition": "2015", "confidence": "high", "kind": "summary", "license": "summary"},
{"id": "mfr-acpa-install-1", "state": "US", "tier": "shelf", "title": "Concrete pipe (RCP) Standard Installations Types 1 to 4: bedding thickness and compaction (ACPA, ASTM C1479)", "topic": "Pipe installation guides by material", "text": "Reinforced concrete pipe installation, summarized from the American Concrete Pipe Association installation manual. The four Standard Installations (Type 1 best, Type 4 least effort) are the same ones in ASTM C1479 and ASCE 15, and the plans say which type the pipe class was designed for. Bedding thickness under the pipe: outside diameter divided by 24, not less than 3 inches; on rock, outside diameter divided by 12, not less than 6 inches. Leave the middle bedding under the pipe loose so the pipe seats. Soil categories: I clean gravelly sand, II sandy silt, III silty clay. Haunch and outer bedding compaction (Standard Proctor): Type 1, 95 percent Category I; Type 2, 90 percent Category I or 95 percent Category II; Type 3, 85 percent Category I, 90 percent II or 95 percent III; Type 4, none needed except 85 percent if Category III soil is used. Lower side: Type 1, 90 percent I, 95 percent II or 100 percent III; Types 2 and 3, 85 percent I, 90 percent II or 95 percent III. Trench width guide: 1.25 times the pipe outside diameter plus 1 foot. Lay from the outlet end with bells upstream; clean and lubricate bell, spigot and gasket; bar and block works up to about 24 inch, larger pipe needs a puller. Put at least 3 feet of compacted backfill over pipe or box before equipment crosses unless it was designed for that load.", "source": "American Concrete Pipe Association, Concrete Pipe and Box Culvert Installation manual (our summary; read 2026-11-20). Standard Installations are the ones in ASTM C1479 and ASCE 15.", "url": "https://concretepipe.org/wp-content/uploads/2014/07/installation_guide.pdf", "checked": "2026-11-20", "edition": "undated", "confidence": "medium", "kind": "summary", "license": "summary"},
{"id": "mfr-westlake-c900-1", "state": "US", "tier": "shelf", "title": "C900 PVC water pipe installation (AWWA C605): trench, cover, joints, bending, testing rules", "topic": "Pipe installation guides by material", "text": "C900 PVC pressure pipe installation, summarized from Westlake Pipe's 2025 installation guides, which follow AWWA C605 (the PVC pressure pipe installation standard) and AWWA manual M23. Trench: clear width at the pipe springline at least 18 inches or pipe OD plus 1 foot, whichever is greater; no more than pipe diameter plus 2 feet at the crown; 4 inches of soil cushion where there is rock. Embedment: work material under the haunches, particle size 3/4 inch or smaller, at least 1 foot of initial backfill over the crown, compacted to what the engineer specifies. Cover: 24 inches under heavy traffic (ASTM D2774). Flotation: about 1.5 pipe diameters of cover. Joints: clean, check the gasket, lubricate the spigot bevel and the gasket with potable-safe lubricant, keep the lengths straight and push to the insertion line without over-inserting. Joint deflection for this pipe is only 1 degree (about 4-3/16 inches of offset on a 20-foot length). Bending the barrel instead is allowed by hand in 12 inch and smaller: minimum radius about 100 feet for 4 inch, 144 feet for 6 inch, 189 feet for 8 inch, 231 feet for 10 inch, 275 feet for 12 inch; never bend and deflect the same length. PVC grows or shrinks about 0.36 inch per 100 feet for each 10 F. Field cuts: square, bevel, re-mark the insertion line. No direct taps on C909 PVCO pipe. Testing: water only, never air; fill at 1 foot per second or less and vent high points; never test above the pipe's pressure rating; disinfect per AWWA C651. Up to two years of outdoor sun exposure is acceptable. Other makers' limits differ, so use the guide for the pipe on the truck.", "source": "Westlake Pipe & Fittings, Installation Guide for C900 PVC and C909 PVCO pressure pipe, MU-IG-013-US-EN-1025.1, 2025; and Municipal Installation Guide MU-IG-017, 2025 (our summary; read 2026-11-20). Both follow AWWA C605.", "url": "https://www.westlakepipe.com/sites/default/files/2025-10/mu-ig-013-us-en-1025.1_c900-pvc-c909-pvco.pdf", "checked": "2026-11-20", "edition": "2025", "confidence": "high", "kind": "summary", "license": "summary"},
{"id": "mfr-jmeagle-solvent-1", "state": "US", "tier": "shelf", "title": "JM Eagle solvent-weld PVC pipe and conduit: trench, cover, cement set times (JME-07B)", "topic": "Pipe installation guides by material", "text": "Solvent-weld PVC pressure pipe and PVC electrical conduit, summarized from JM Eagle's installation guide JME-07B (revised March 2011). Bedding 4 to 6 inches compacted, with bell holes; on rock, a cushion of at least 4 inches of sand or select backfill (6 inches in rock cuts). Haunching and initial backfill by hand, no rocks over 1.5 inches, tamped in layers of 6 inches or less, to at least 1 foot above the pipe; 90 percent density under pavement. Trench width: pipe OD plus 1 foot minimum at the springline, pipe OD plus 2 feet maximum at the top of the pipe. Cover: 12 inches where frost is not a concern, otherwise 6 inches below the deepest recorded frost. No rolling equipment until 18 inches of backfill is over the pipe; hydro-hammers need at least 3 feet. Solvent joints: dry fit (pipe should go 1/3 to 3/4 of the way into the socket), prime, cement both parts, push home with a quarter turn, look for a full bead. Minimum set time before handling: 30 minutes at 60 to 100 F, 1 hour at 40 to 60 F, 2 hours at 20 to 40 F, 4 hours at 0 to 20 F. No deflection at solvent joints: make curves by bending the pipe; snake small pipe in the trench. Pressure test is generally 25 percent above normal operating pressure and never above the pipe's rating. Never use compressed air or gas in PVC pressure pipe. JM Eagle's gravity sewer guide is JME-05B.", "source": "JM Eagle (J-M Manufacturing), Solvent Weld and Electrical Conduit Installation Guide, JME-07B, revised March 2011 (our summary; read 2026-11-20)", "url": "https://images.thdstatic.com/catalog/pdfImages/55/5515bbf2-b7ff-4f77-b3f6-c061e3e6beec.pdf", "checked": "2026-11-20", "edition": "2011", "confidence": "high", "kind": "summary", "license": "summary"},
{"id": "mfr-contech-cmp-1", "state": "US", "tier": "shelf", "title": "Corrugated metal pipe (CMP) installation: bedding, 8-inch lifts, 90 percent, balanced backfill, cover (Contech)", "topic": "Pipe installation guides by material", "text": "Corrugated metal pipe installation, summarized from Contech's CMP Installation Guide (June 2023). Bedding: 4 to 6 inches of well-graded granular material on a firm foundation; dig out soft spots and replace with granular fill. Backfill: angular, well-graded granular soil (AASHTO A-1, A-2 or A-3), nothing over 3 inches, placed in loose lifts of about 8 inches and compacted to 90 percent of AASHTO T99 (95 percent in the haunches of pipe-arch). Work material into the haunches with a shovel or rod. Keep the two sides balanced: never let one side get more than 24 inches higher than the other, including between barrels. Use flowable fill (CLSM) in thin lifts where barrels are too close to compact, letting each lift set so the pipe does not float. Minimum cover for highway loads is span divided by 8 (not less than 12 inches in common practice), in place and compacted before traffic. Light tracked equipment such as a small dozer needs at least 12 inches of compacted cover; heavy construction equipment needs more per the guide's tables. Lay from the downstream end and build the outlet first so rain can drain. Unload with forks or non-metallic slings; never dump pipe off the truck or lift bundles by the strapping.", "source": "Contech Engineered Solutions, CMP Installation Guide, June 2023 (our summary; read 2026-11-20)", "url": "https://conteches.com/media/uyslalti/cmp-installation-guide.pdf", "checked": "2026-11-20", "edition": "2023", "confidence": "high", "kind": "summary", "license": "summary"},
{"id": "mfr-westlake-sewer-1", "state": "US", "tier": "shelf", "title": "PVC gravity sewer pipe (SDR 35): cover before traffic, joint deflection and bending limits (Westlake guide)", "topic": "Pipe installation guides by material", "text": "PVC gravity sewer pipe (ASTM D3034), summarized from Westlake Pipe's 2024 installation guide. Embedment follows ASTM D2321 Classes I to IV. Cover before traffic crosses: 24 inches or one pipe diameter, whichever is larger, with Class I (crushed rock) embedment; 36 inches or one pipe diameter with Classes II to IV; 48 inches before a hydrohammer is used over the pipe. Flotation: about 1.5 pipe diameters of cover for SDR 32.5 and heavier pipe. Deflection: the guide uses 7.5 percent maximum at 30 days (ASTM D3034 appendix), checked with a go/no-go mandrel after 30 days; many agencies specify 5 percent. Joints: clean, lubricate the spigot bevel and gasket, keep the lengths straight, push with bar and block until the bell edge is on the insertion line, and do not over-insert. Joint deflection for this pipe is 1 degree: about 2.9 inches of offset on a 14-foot length and 4.2 inches on a 20-foot length. Bending the barrel by hand instead: minimum radius about 35 feet for 4 inch, 52 feet for 6 inch, 70 feet for 8 inch, 85 feet for 10 inch, 104 feet for 12 inch and 128 feet for 15 inch; not recommended above 15 inch; never bend and deflect the same length. Low-pressure air testing follows ASTM F1417. Laying lengths are 14 and 20 feet.", "source": "Westlake Pipe & Fittings, ASTM D3034 PVC Gravity Sewer Pipe Installation Guide, MU-IG-003-US-EN-0724.1, 2024 (our summary; read 2026-11-20)", "url": "https://www.westlakepipe.com/sites/default/files/2024-10/mu-ig-003-us-en-0724.1_astm-d3034.pdf", "checked": "2026-11-20", "edition": "2024", "confidence": "high", "kind": "summary", "license": "summary"},
{"id": "fed-epa-cgp-paperwork-1", "state": "US", "title": "SWPPP paperwork for the office: NOI, plan on site, records 3 years, termination in 30 days", "topic": "Stormwater on the job: construction general permit, SWPPP, inspections, dewatering", "text": "Office checklist from EPA's 2022 Construction General Permit. Before work: write the stormwater pollution prevention plan (SWPPP) before filing the Notice of Intent (Part 7.1), and file the NOI \"At least 14 calendar days before commencing construction activities\" (Part 1.4.3). During work: keep a current SWPPP \"at the site or at an easily accessible location\" so it can be shown to an inspector (Part 7.3); update it when the controls or the plan change. Use a qualified inspector (EPA course and exam, or an equivalent current certification, for projects covered on or after February 17, 2023; Part 6.3). Log every corrective action and close it within the permit's deadlines (7 calendar days for a new or replaced control or significant repair). Records: keep inspection reports and the corrective action log \"for at least three (3) years\" after coverage ends (Parts 4.7.4, 5.4.4). After work: file the Notice of Termination \"within 30 calendar days after any one of the conditions in Part 8.2 occurs\", for example the site is finally stabilized or another operator has taken over (Part 8.4). A pipe subcontractor is often a co-operator or works under the general contractor's SWPPP: get that in writing and know which controls are yours to maintain. These are EPA's own permit numbers. Most states issue their own permit, usually close to this, and the state permit governs there.", "source": "EPA 2022 Construction General Permit, as modified April 2025, Parts 1.4.3, 6.3, 7.1, 7.3, 4.7.4, 5.4.4, 8.4", "url": "https://www.epa.gov/system/files/documents/2025-04/2022-cgp-permit-as-modified.pdf", "checked": "2026-11-20", "edition": "2022 CGP as modified (effective April 8, 2025); expires February 16, 2027", "confidence": "high", "kind": "summary", "license": "gov-us", "tier": "shelf"},
{"id": "fed-achp-discovery-1", "state": "US", "title": "Bones, artifacts or old foundations in the trench: stop and call it in", "topic": "Unexpected finds in the trench: human remains and artifacts", "text": "If the bucket turns up bones that could be human, a burial, arrowheads or other artifacts, old bottles and foundations, or anything that looks like an archaeological site: stop digging at that spot, keep people and equipment off it, do not move or pocket anything, and call the foreman, who calls the owner or inspector. Possible human remains also means a call to the police or the county coroner or medical examiner. On a job with federal money, a federal permit or federal land, the project went through historic review (Section 106), and 36 CFR 800.13 covers a find after construction has started: the federal agency must \"make reasonable efforts to avoid, minimize or mitigate adverse effects\" and, once construction is under way, notify the state or tribal historic preservation officer, affected tribes and the Advisory Council within 48 hours of the discovery; they have 48 hours to respond. Many projects have a written \"inadvertent discovery plan\" in the permit or specs that names who to call: ask for it at the preconstruction meeting. State law usually has its own stop-work rule for human remains. For example the California Health and Safety Code, section 7050.5, says \"there shall be no further excavation or disturbance of the site\" until the county coroner has decided, and the coroner calls the Native American Heritage Commission within 24 hours if the remains may be Native American. Work can usually go on elsewhere on the job while the spot is checked.", "source": "36 CFR 800.13(b) (post-review discoveries); Cal. Health and Safety Code 7050.5(b)-(c) as an example of state law", "url": "https://codes.findlaw.com/cfr/title-36-parks-forests-and-public-property/cfr-sect-36-800-13/", "checked": "2026-11-20", "edition": "36 CFR Part 800 as shown on codes.findlaw.com, read 2026-11-20", "confidence": "medium", "kind": "summary", "license": "gov-us", "tier": "shelf"},
{"id": "fed-law-miller-act-1", "state": "US", "title": "Not getting paid on a federal job: the Miller Act payment bond (90 day notice, 1 year to sue)", "topic": "Prevailing wage paperwork: certified payroll and payment bonds", "text": "You cannot lien federal property. Instead the Miller Act (40 U.S.C. 3131 to 3134) makes the prime contractor post a payment bond \"Before any contract of more than $100,000 is awarded\" for a federal construction job (the acquisition regulations set the working threshold higher; the library's bonds chunk gives $150,000). Who can claim: subcontractors and suppliers who dealt directly with the prime, and second-tier subs and suppliers who dealt with a first-tier subcontractor. Third tier and below are generally not covered. First tier (contract with the prime): no notice is needed; a claimant who \"has not been paid in full within 90 days after the day on which the person did or performed the last of the labor\" or furnished the last material may sue on the bond. Second tier (contract with a subcontractor, none with the prime): must give \"written notice to the contractor within 90 days\" of its last labor or material, stating the amount and who the work was done for, sent \"by any means that provides written, third-party verification of delivery to the contractor\" (certified mail or a delivery service with a receipt). Deadline to sue for everyone: the suit \"must be brought no later than one year after the day on which the last of the labor was performed\" or material supplied. Punch-list and warranty work may not extend that date. A waiver of these rights signed before the work is done is void. Get the bond copy from the contracting officer at the start of the job. For a real claim, use a construction attorney: the dates are strict.", "source": "40 U.S.C. 3131(b), 3133(b)(1), (b)(2), (b)(4), (c) (U.S. Code 2023 edition)", "url": "https://www.govinfo.gov/content/pkg/USCODE-2023-title40/html/USCODE-2023-title40-subtitleII-partA-chap31-subchapIII.htm", "checked": "2026-11-20", "edition": "U.S. Code, 2023 edition", "confidence": "high", "kind": "summary", "license": "gov-us", "tier": "shelf"},
{"id": "lic-ca-prelim-notice-1", "state": "CA", "title": "California 20-day preliminary notice: protecting the right to get paid (private and public jobs)", "topic": "Getting paid: preliminary notices, liens and stop payment notices", "checked": "2026-11-20", "confidence": "high", "kind": "summary", "license": "gov-state", "text": "In California a subcontractor or supplier keeps its right to a mechanics lien, a stop payment notice or a payment bond claim by giving a preliminary notice early in the job. Private jobs (Civil Code 8204): the notice is due \"not later than 20 days after the claimant has first furnished work\" on the job. A late notice still helps, but then the lien, stop payment notice or bond claim only covers work \"performed within 20 days prior to the service of the preliminary notice\" and after it. So every day late is money that can no longer be secured. Public works (Civil Code 9300): before giving a stop payment notice or making a payment bond claim, the claimant gives preliminary notice to \"The public entity.\" and \"The direct contractor to which the claimant provides work.\" Two groups do not have to give it on public works: \"A laborer is not required to give preliminary notice\", and neither is a claimant with a direct contract with the direct (prime) contractor. So a pipe sub hired by the general contractor on a city job is exempt, but its pipe supplier and its own subs are not. Public property cannot be liened; the stop payment notice and the payment bond are the remedies there. Office habit that works: send the notice by certified mail on every job in the first week, before there is any problem. For a real claim, the later deadlines are strict: use a construction attorney.", "source": "Cal. Civil Code 8204 and 9300 (as shown on california.public.law); read 2026-11-20", "url": "https://california.public.law/codes/ca_civ_code_section_8204", "edition": "California Civil Code as shown 2026-11-20", "note": "No library collection exists for state payment / lien law; filed under lic- for now. The architecture helper should say where it belongs.", "tier": "shelf"}]$kb$::jsonb) e
on conflict (id) do update set chunk = excluded.chunk where pb_ai.kb_shelf.chunk is distinct from excluded.chunk;
select count(*) as shelf_rows from pb_ai.kb_shelf;
commit;
